export const HTML="<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>채용 설문지 만들기</title><style>\n:root{--blue:#065aec;--ink:#14243d;--muted:#546175;--line:#d7dfe9;--bg:#f1f4f9}*{box-sizing:border-box}body{margin:0;font:16px/1.6 'Malgun Gothic','Apple SD Gothic Neo',sans-serif;color:var(--ink);word-break:keep-all;background:var(--bg)}button,input,textarea{font:inherit}button{cursor:pointer;background:white;border:1px solid var(--line);border-radius:9px;min-height:44px;padding:8px 14px;color:inherit}button:hover{border-color:var(--blue)}button:disabled{cursor:default;opacity:.45}button:focus-visible,input:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid #77acff;outline-offset:3px}header{background:white;padding:20px 30px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:24px}header h1{font-size:25px;margin:0}p{color:var(--muted);margin:6px 0 20px}h2{font-size:21px;margin:0}h3{font-size:18px}main{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:16px;height:calc(100dvh - 82px)}.panel{min-width:0;border:1px solid var(--line);border-radius:12px;background:white;overflow:auto}.editor{padding:24px}.section{margin-bottom:28px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}.count{color:var(--blue);font-weight:bold;white-space:nowrap}.traits{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.trait{font-size:14px;padding:8px 4px}.selected{background:#eaf2ff;border-color:#77aaff;color:#064cbd;font-weight:bold}.tabs{display:flex;gap:6px;margin:16px 0;flex-wrap:wrap}.tabs button{flex:1;white-space:nowrap}.qrow{display:flex;align-items:flex-start;gap:12px;padding:14px 4px;border-bottom:1px solid #e9edf3;cursor:pointer}.qrow:has(input:checked){background:#f4f8ff}.qrow input{width:19px;height:19px;accent-color:var(--blue);flex-shrink:0;margin-top:5px}.qrow:has(input:disabled){color:#758093}.type{display:block;color:var(--muted);font-size:13px;margin-bottom:3px}.question-list{max-height:440px;overflow:auto}.custom{border-top:1px solid var(--line);padding-top:24px}.custom textarea{width:100%;min-height:95px;padding:12px;border:1px solid #9aa9bd;border-radius:8px;resize:vertical}.custom button{margin-top:8px}.customitem{display:flex;gap:12px;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}.customitem span{white-space:pre-wrap;overflow-wrap:anywhere}.customitem button{flex-shrink:0}.preview{background:#eaf0f7;display:flex;flex-direction:column;overflow:hidden}.toolbar{padding:20px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.primary{background:var(--blue);color:white;border-color:var(--blue);font-weight:bold}.paperwrap{overflow:auto;padding:0 16px 20px;flex:1}.paper{background:white;padding:32px;border:1px solid var(--line);border-radius:10px;min-height:100%}.paper h1{font-size:27px;margin:0 0 8px}.group-title{margin:30px 0 20px;color:#123d7b;background:#eaf2ff;display:inline-block;padding:4px 12px;border-radius:6px;font-size:15px}.answer{margin-bottom:28px}.answer label{font-weight:bold;display:block;margin-bottom:12px;white-space:pre-wrap;overflow-wrap:anywhere}.answer textarea{width:100%;min-height:125px;resize:vertical;padding:14px;border:1px solid #9aa9bd;border-radius:8px}.empty{text-align:center;padding:70px 12px;color:var(--muted)}.empty b{display:block;font-size:20px;color:var(--ink);margin-bottom:12px}.note{font-size:13px;color:var(--muted)}.status{min-height:24px;color:#a13030;font-size:14px}.standalone main{display:block;height:auto;max-width:850px;margin:auto;padding:28px 16px}.standalone header,.standalone .editor,.standalone .toolbar{display:none}.standalone .preview{border:none;background:transparent;overflow:visible}.standalone .paperwrap{padding:0;overflow:visible}.standalone .paper{min-height:0}.standalone .survey-note{display:block}.survey-note{display:none}dialog{border:0;border-radius:16px;max-width:580px;width:calc(100% - 32px);padding:28px;color:var(--ink)}dialog::backdrop{background:#14243d88}dialog input{width:100%;padding:12px;border:1px solid #9aa9bd;border-radius:8px;margin:12px 0}dialog .actions{display:flex;gap:10px;flex-wrap:wrap}dialog a{display:inline-flex;align-items:center;padding:8px;color:var(--blue)}@media(max-width:1100px){.traits{grid-template-columns:repeat(3,1fr)}.editor{padding:18px}.paper{padding:24px}}@media(max-width:760px){header{padding:18px}header h1{font-size:21px}header p{display:none}main{display:block;height:auto;padding:10px}.panel{margin-bottom:16px}.preview{min-height:500px}.paperwrap{max-height:70dvh}.traits{grid-template-columns:repeat(3,1fr)}.standalone .paperwrap{max-height:none}.toolbar{padding:16px}.paper{padding:20px}.paper h1{font-size:24px}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s,border-color .15s}} \n</style></head><body><header><h1>채용 설문지 만들기</h1><p style=\"margin:0\">우리 매장에 맞는 질문을 골라보세요</p><a href=\"/admin\" style=\"margin-left:auto;flex-shrink:0;text-decoration:none;border:1px solid var(--line);border-radius:9px;padding:10px 16px;color:var(--blue);font-weight:bold\">지원자 응답 확인 <span id=\"unreadBadge\" hidden style=\"background:#eaf2ff;border-radius:20px;padding:3px 8px;font-size:13px\"></span></a></header><main><section class=\"panel editor\" aria-label=\"설문지 편집\"><div class=\"section\"><div class=\"row\"><h2>1. 인재상 선택</h2><span class=\"count\" id=\"traitCount\">0 / 3</span></div><p>최대 3개까지 선택할 수 있어요.</p><div id=\"traits\" class=\"traits\"></div></div><div class=\"section\"><h2>2. 질문 선택</h2><p>선택한 인재상의 질문을 합쳐서 총 10개를 골라주세요.</p><div id=\"tabs\" class=\"tabs\"></div><div id=\"questionList\" class=\"question-list\"></div></div><section class=\"custom\"><h2>3. 직접 질문 추가</h2><p>사장님이 더 묻고 싶은 내용을 넣어주세요.</p><label for=\"customText\" class=\"note\">추가할 질문</label><textarea id=\"customText\" maxlength=\"500\" placeholder=\"예: 우리 매장에서 일하며 배우고 싶은 것은 무엇인가요?\"></textarea><button id=\"addCustom\">질문 추가</button><div id=\"customList\"></div></section><p id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\"></p></section><section class=\"panel preview\" aria-label=\"설문지 미리보기\"><div class=\"toolbar\"><div><h2>설문지 미리보기</h2><span id=\"total\" class=\"note\">총 0문항</span></div><button class=\"primary\" id=\"share\" disabled>설문 링크 만들기</button><span class=\"note\" id=\"remaining\">인재상을 선택하고 질문을 골라주세요.</span></div><div class=\"paperwrap\"><article class=\"paper\"><h1>외식업 신규 채용 설문지</h1><p>정답은 없어요. 본인의 경험과 생각을 편하게 적어주세요.</p><p class=\"note survey-note\">답변은 이 탭에 임시 저장돼요. 제출하면 담당자가 지원자 정보와 답변을 확인할 수 있어요.</p><form id=\"application\"><fieldset id=\"identity\" class=\"survey-note\" style=\"border:0;padding:0;margin:24px 0\"><legend><h2>지원자 정보</h2></legend><label for=\"appName\">이름</label><input id=\"appName\" name=\"name\" autocomplete=\"name\" maxlength=\"60\" style=\"display:block;width:100%;padding:12px;margin:8px 0 16px\"><label for=\"appBirth\">생년월일</label><input id=\"appBirth\" name=\"birth\" type=\"date\" style=\"display:block;width:100%;padding:12px;margin:8px 0 16px\"><label for=\"appPhone\">전화번호</label><input id=\"appPhone\" name=\"phone\" type=\"tel\" autocomplete=\"tel\" maxlength=\"25\" placeholder=\"010-1234-5678\" style=\"display:block;width:100%;padding:12px;margin:8px 0 16px\"></fieldset><div id=\"survey\"></div><div class=\"survey-note\"><p class=\"note\">이름, 생년월일, 전화번호와 답변은 채용 담당자가 확인할 수 있도록 서버에 저장돼요.</p><button id=\"submitApplication\" type=\"submit\" class=\"primary\">제출하기</button><p id=\"submitStatus\" role=\"status\" aria-live=\"polite\"></p></div></form></article></div></section></main><dialog id=\"linkDialog\"><h2>설문 링크를 만들었어요</h2><p>이 링크에서는 완성된 설문지만 열려요.</p><label for=\"shareUrl\">설문지 주소</label><input id=\"shareUrl\" readonly><div class=\"actions\"><button id=\"copy\" class=\"primary\">링크 복사</button><a id=\"openSurvey\" target=\"_blank\" rel=\"noopener\">설문지 열기</a><button id=\"closeDialog\">닫기</button></div><p class=\"note\" id=\"shareNote\">현재 사이트는 제작자 전용이에요. 외부 지원자에게 공유하려면 사이트 공개 설정이 필요해요.</p><p id=\"copyStatus\" role=\"status\"></p></dialog><script id=\"bank\" type=\"application/json\">[{\"name\": \"성실함\", \"questions\": [\"단순한 준비 작업을 여러 날 반복하면서도 빠뜨리지 않았던 경험을 설명해 주세요.\", \"손님이 적은 시간에도 맡은 일을 끝까지 수행한 경험이 있나요?\", \"다른 사람이 확인하지 않는 업무를 꾸준히 처리했던 방법은 무엇인가요?\", \"처음에는 의욕이 있었지만 점차 지루해진 일을 어떻게 이어 갔나요?\", \"결과가 바로 보이지 않는 연습을 지속했던 경험을 이야기해 주세요.\", \"마감 무렵 집중력이 떨어졌을 때 남은 작업을 어떻게 마쳤나요?\", \"자신이 정한 작은 업무 습관을 오래 유지한 사례를 설명해 주세요.\", \"반복 업무를 대충 처리하고 싶었던 순간에 실제로 어떻게 행동했나요?\", \"작업량이 평소보다 많아도 기본 절차를 유지했던 경험이 있나요?\", \"중간에 흐트러진 업무 습관을 다시 바로잡았던 과정을 설명해 주세요.\", \"예약이 없는 날에도 식기 준비량을 맞춰야 한다면 어떻게 일하겠나요?\", \"반응이 없는 연습 과제를 일주일 더 해야 한다면 어떻게 지속하겠나요?\", \"동료가 소스통 채우기를 매번 내일로 미루자고 하면 어떻게 하겠나요?\", \"손님에게 보이지 않는 창고 정리를 맡으면 어떤 순서로 끝내겠나요?\", \"같은 채소 손질을 한 시간째 하고 있다면 집중력을 어떻게 유지하겠나요?\", \"마감 직전 아직 냅킨 접기가 남았다면 어떻게 마무리하겠나요?\", \"익숙해진 개점 준비에서 자꾸 한 가지가 빠진다면 무엇을 바꾸겠나요?\", \"며칠간 한가해 준비 기준을 느슨하게 지키게 된다면 어떻게 바로잡겠나요?\", \"혼자 근무하는 구역에서 점검을 생략하고 싶어진다면 어떻게 하겠나요?\", \"반복 작업의 완료량이 기대보다 적다면 남은 시간을 어떻게 쓰겠나요?\", \"맡은 일을 성실히 했다고 판단하는 본인만의 기준은 무엇인가요?\", \"누군가 지켜볼 때와 혼자 일할 때 태도를 같게 유지하려면 무엇이 필요한가요?\", \"눈에 띄는 업무와 보조 업무에 쏟는 노력을 어떻게 배분하나요?\", \"반복 업무를 오래 수행할 때 스스로 점검하는 신호는 무엇인가요?\", \"성과에 대한 칭찬이 없어도 꾸준히 일하게 하는 이유는 무엇인가요?\", \"하루 업무를 대충 끝내지 않기 위해 어떤 마무리 습관을 두고 싶나요?\", \"익숙한 일을 할수록 오히려 신경 써야 할 부분은 무엇이라고 생각하나요?\", \"의욕에 따라 작업 수준이 달라지지 않게 하려면 어떻게 해야 하나요?\", \"하기 싫은 업무가 반복될 때 자신과 어떤 약속을 하겠나요?\", \"첫 달의 성실함을 몇 달 뒤에도 유지하기 위한 계획을 설명해 주세요.\"]}, {\"name\": \"책임감\", \"questions\": [\"본인의 실수로 다른 사람에게 일이 생겼을 때 어떻게 수습했나요?\", \"맡은 업무의 결과를 마지막까지 확인했던 경험을 설명해 주세요.\", \"끝내지 못한 일을 다음 담당자에게 넘겼던 과정을 이야기해 주세요.\", \"본인 역할이 모호한 문제에서 책임 범위를 확인한 경험이 있나요?\", \"실수를 보고하기 망설였지만 직접 알렸던 경험을 설명해 주세요.\", \"자신이 시작한 작업이 예상보다 커졌을 때 어떻게 마무리했나요?\", \"문제가 해결된 줄 알았으나 다시 발생했던 일을 어떻게 처리했나요?\", \"팀의 결과가 좋지 않았을 때 본인 몫을 돌아본 경험이 있나요?\", \"다른 사람이 대신 처리해 준 일에 대해 이후 어떤 행동을 했나요?\", \"실수 이후 재발 여부를 직접 확인했던 사례를 설명해 주세요.\", \"본인이 잘못 입력한 주문이 조리 중이라면 어떻게 수습하겠나요?\", \"담당한 예약 확인을 놓쳐 좌석이 부족해졌다면 어떻게 대응하겠나요?\", \"퇴근 시간이 됐는데 본인이 맡은 환불 처리가 남았다면 어떻게 하겠나요?\", \"직접 포장한 주문에서 상품 누락이 확인되면 어떤 조치를 하겠나요?\", \"자신이 확인했다고 말한 재고가 실제와 다르면 어떻게 처리하겠나요?\", \"실수 원인이 본인과 동료 모두에게 있다면 어떻게 보고하겠나요?\", \"고객에게 전달하기로 한 안내가 누락됐음을 뒤늦게 알면 어떻게 하겠나요?\", \"본인이 수리 요청한 장비의 상태가 여전히 불안정하면 어떻게 하겠나요?\", \"맡은 행사 준비를 정해진 시간까지 못 끝낼 것 같다면 어떻게 알리겠나요?\", \"해결한 불만 고객이 다시 연락한다면 이전 처리 내용을 어떻게 확인하겠나요?\", \"업무를 맡았다는 것에 결과 확인이 어디까지 포함된다고 생각하나요?\", \"실수의 이유를 설명하는 것과 책임을 피하는 것은 어떻게 다른가요?\", \"본인 권한으로 해결할 수 없는 문제에는 어떤 책임이 남는다고 보나요?\", \"업무 인계를 완료했다고 판단하려면 무엇을 확인해야 하나요?\", \"문제가 발생한 뒤 사과 외에 반드시 필요한 행동은 무엇인가요?\", \"공동 업무의 책임이 흐려지지 않게 하려면 어떻게 역할을 정해야 하나요?\", \"실패를 보고할 때 어떤 내용을 빠뜨리지 않아야 한다고 생각하나요?\", \"맡은 일을 끝내기 어렵다는 사실은 어느 시점에 알려야 하나요?\", \"본인 실수의 영향을 확인할 때 누구의 업무까지 살펴보겠나요?\", \"수습이 끝난 일을 다시 돌아볼 때 어떤 질문을 스스로 하겠나요?\"]}, {\"name\": \"정직함\", \"questions\": [\"본인에게 불리한 사실을 숨기지 않고 말했던 경험을 설명해 주세요.\", \"잘 모르는 내용을 아는 척하지 않고 확인했던 경험이 있나요?\", \"기록과 실제 결과가 다른 것을 발견했을 때 어떻게 했나요?\", \"실제로 하지 않은 일에 대해 칭찬받았을 때 어떻게 반응했나요?\", \"실수의 규모를 줄여 말하고 싶었던 상황에서 무엇을 선택했나요?\", \"다른 사람의 부탁으로 사실과 다르게 말해야 했던 상황을 어떻게 처리했나요?\", \"계산이나 정산에서 본인에게 유리한 오류를 발견한 경험이 있나요?\", \"추측을 사실처럼 전달했다가 바로잡았던 경험을 설명해 주세요.\", \"약속한 결과를 달성하지 못했음을 솔직히 알린 경험이 있나요?\", \"잘못 작성한 기록을 원래 내용이 드러나도록 수정한 경험을 말해 주세요.\", \"결제 금액을 더 받았는데 고객이 알아채지 못했다면 어떻게 하겠나요?\", \"점검하지 않은 냉장고의 온도를 적으라는 요청을 받으면 어떻게 하겠나요?\", \"음식이 떨어졌는데 깨끗하니 그냥 내자는 말을 들으면 어떻게 대응하겠나요?\", \"품절 이유를 모르는 상태에서 고객이 설명을 요구하면 무엇이라고 하겠나요?\", \"파손한 컵을 누가 깼는지 매니저가 묻는다면 어떻게 설명하겠나요?\", \"동료가 자신의 지각 기록을 대신 수정해 달라고 하면 어떻게 하겠나요?\", \"할인 조건에 맞지 않는 주문을 맞는 것처럼 처리하자고 하면 어떻게 하겠나요?\", \"재료 원산지를 확실히 모르는데 고객이 물으면 어떻게 답하겠나요?\", \"실수로 받은 추가 거스름돈을 퇴근 후 발견한다면 어떻게 하겠나요?\", \"본인이 목격하지 않은 일을 증언해 달라는 요청을 받으면 어떻게 하겠나요?\", \"업무 보고에서 직접 본 사실과 추정을 어떻게 구분해 말하나요?\", \"고객을 안심시키려는 말도 사실 확인이 필요한 이유는 무엇인가요?\", \"사소한 기록 오류를 발견했을 때 수정 여부를 무엇으로 판단하나요?\", \"솔직하게 말하기 어려운 상황에서 지키고 싶은 원칙은 무엇인가요?\", \"모른다고 답할 때 상대의 신뢰를 얻으려면 무엇을 덧붙여야 하나요?\", \"매출이나 폐기량을 실제와 다르게 적으면 어떤 문제가 생길까요?\", \"좋은 의도로 한 과장도 업무에 영향을 줄 수 있는 이유는 무엇인가요?\", \"사실을 바로잡는 과정에서 동료의 체면을 어떻게 고려하겠나요?\", \"확인되지 않은 매장 소문을 들었을 때 어떤 태도를 취하겠나요?\", \"정직한 보고를 하기 어려운 분위기에서는 어떤 방식으로 사실을 전달하겠나요?\"]}, {\"name\": \"근태 준수\", \"questions\": [\"정해진 시작 시간에 맞추기 위해 준비 과정을 조정한 경험을 설명해 주세요.\", \"이동 중 예상치 못한 지연이 생겼을 때 어떻게 연락했나요?\", \"일정을 잘못 확인한 적이 있다면 이후 확인 방법을 어떻게 바꿨나요?\", \"참석이 어려워진 약속을 미리 조율했던 경험을 말해 주세요.\", \"일정이 자주 바뀌는 활동에서 출석을 관리했던 방법은 무엇인가요?\", \"휴식 후 정해진 시간에 복귀하기 위해 사용한 방법이 있나요?\", \"다른 사람과 시간을 바꾸면서 혼선을 막았던 경험을 설명해 주세요.\", \"시작 시간을 잘 지키지 못하던 습관을 고친 경험이 있나요?\", \"여러 일정이 겹쳤을 때 기존 약속을 어떻게 조정했나요?\", \"출퇴근이나 참석 기록의 오류를 발견했을 때 어떻게 처리했나요?\", \"출근길 교통 지연으로 늦을 가능성이 생기면 언제 무엇을 알리겠나요?\", \"게시된 근무표와 전달받은 시간이 다르면 어떻게 확인하겠나요?\", \"다음 주 확정 근무를 바꿔야 한다면 어떤 절차로 요청하겠나요?\", \"교대 약속을 한 동료가 답변을 주지 않으면 어떻게 하겠나요?\", \"갑작스러운 사정으로 당일 출근이 어려워지면 어떤 순서로 연락하겠나요?\", \"휴게 종료 시간이 다가왔는데 복귀가 늦어질 상황이면 어떻게 하겠나요?\", \"출근했지만 근태 기록을 빠뜨렸음을 알게 되면 어떻게 하겠나요?\", \"근무표가 변경됐는데 본인 확인 표시가 없다면 무엇을 점검하겠나요?\", \"퇴근 시각 이후 업무 요청을 받으면 근무시간을 어떻게 확인·조율하겠나요?\", \"출근 시간에 반복적으로 아슬아슬하게 도착한다면 무엇을 바꾸겠나요?\", \"근무 가능 시간을 전달할 때 어느 정도까지 확인한 뒤 답하나요?\", \"근무 일정 변경이 확정됐다고 판단하는 기준은 무엇인가요?\", \"늦을 가능성을 알리는 연락에는 어떤 정보가 있어야 하나요?\", \"출근 시각과 실제 업무 시작 준비를 어떻게 맞추겠나요?\", \"근무표를 놓치지 않기 위해 어떤 확인 습관을 만들겠나요?\", \"교대를 개인끼리 합의한 뒤에도 매장 확인이 필요한 이유는 무엇인가요?\", \"예정된 휴가나 일정 조정은 어떤 방식으로 미리 공유하고 싶나요?\", \"지각 후 팀의 혼선을 줄이기 위해 어떤 행동이 필요하다고 보나요?\", \"연락 담당자와 연결되지 않을 때 어떤 대체 연락 절차를 확인하겠나요?\", \"안정적으로 지킬 수 있는 근무 일정을 정할 때 무엇을 고려하나요?\"]}, {\"name\": \"신뢰성\", \"questions\": [\"다른 사람이 본인의 진행 상황을 믿고 다음 일을 준비했던 경험이 있나요?\", \"약속을 지키기 어려워지기 전에 상대에게 알린 경험을 설명해 주세요.\", \"한 번 잃은 신뢰를 행동으로 회복했던 경험을 말해 주세요.\", \"작은 요청을 잊지 않고 처리하기 위해 사용했던 방법은 무엇인가요?\", \"말한 내용과 실제 행동을 일치시키기 위해 노력한 경험이 있나요?\", \"여러 사람에게 받은 요청의 처리 상태를 어떻게 공유했나요?\", \"자신이 감당할 수 없는 부탁을 명확히 거절하거나 조정한 경험이 있나요?\", \"중요한 전달사항을 누락 없이 이어 준 경험을 설명해 주세요.\", \"누군가 업무를 안심하고 맡기게 된 계기가 있었다면 무엇인가요?\", \"이전에 전달한 완료 시점을 수정하면서 신뢰를 유지한 경험이 있나요?\", \"10분 뒤 전달하기로 한 자료가 늦어질 것 같다면 어떻게 알리겠나요?\", \"매니저가 처리 여부를 묻기 전에 어떤 방식으로 완료 사실을 공유하겠나요?\", \"동료가 본인의 준비 완료를 전제로 단체석을 열려 한다면 무엇을 확인하겠나요?\", \"같은 고객의 요청을 두 직원이 각각 맡았다면 약속을 어떻게 정리하겠나요?\", \"대신 전달해 달라는 말을 받았지만 담당자를 못 만나면 어떻게 하겠나요?\", \"확답하기 어려운 제공 시간을 고객이 요구하면 어떻게 답하겠나요?\", \"이전 교대자가 본인의 인계를 믿지 못한다면 무엇부터 바꾸겠나요?\", \"처리하기로 한 요청이 휴대전화 메모에서 빠졌다면 어떻게 복구하겠나요?\", \"동료가 본인의 업무 범위를 오해하고 기대하고 있다면 어떻게 정리하겠나요?\", \"약속한 점검 결과가 아직 확인 중이라면 중간 상황을 어떻게 전달하겠나요?\", \"동료가 믿고 일을 맡길 수 있는 직원은 어떤 행동을 보인다고 생각하나요?\", \"쉽게 할 수 있다는 말보다 정확한 약속이 필요한 이유는 무엇인가요?\", \"요청을 받았을 때 수락 전에 무엇을 확인하나요?\", \"진행 상황은 어떤 시점마다 공유하는 것이 적절하다고 보나요?\", \"개인 메모와 공동 기록에는 각각 어떤 내용을 남기겠나요?\", \"약속을 지킨 사실을 상대가 알 수 있도록 어떻게 마무리하겠나요?\", \"반복해서 같은 확인을 받는다면 본인의 어떤 행동을 점검하겠나요?\", \"업무 능력을 실제보다 크게 기대받을 때 어떻게 기대를 조정하겠나요?\", \"동료에게 일관된 기준으로 응대하기 위해 무엇을 주의하겠나요?\", \"처음 함께 일하는 동료의 신뢰를 얻기 위해 첫 주에 무엇을 하겠나요?\"]}, {\"name\": \"학습 능력\", \"questions\": [\"처음 접한 기기 사용법을 배워 혼자 다루게 된 과정을 설명해 주세요.\", \"한 번에 외우기 어려운 내용을 어떤 방법으로 익혔나요?\", \"설명만 듣고 이해되지 않았던 작업을 어떻게 배웠나요?\", \"배운 순서를 잊어 실수한 뒤 학습 방법을 바꾼 경험이 있나요?\", \"다른 사람의 시범을 보며 핵심 동작을 찾아낸 경험을 말해 주세요.\", \"연습한 내용을 실제 상황에 적용했을 때 달랐던 점은 무엇인가요?\", \"익숙한 방식 때문에 새로운 방법을 배우기 어려웠던 경험이 있나요?\", \"자신에게 잘 맞는 학습 방법을 발견했던 계기를 설명해 주세요.\", \"여러 정보를 짧은 기간에 배워야 했을 때 어떻게 나누어 익혔나요?\", \"배운 내용을 누군가에게 설명하면서 다시 이해한 경험이 있나요?\", \"메뉴 20개의 구성 재료를 처음 배운다면 어떤 순서로 익히겠나요?\", \"포스 사용법 시범이 너무 빨랐다면 어떻게 추가 학습을 요청하겠나요?\", \"음료 제조 순서가 자꾸 헷갈린다면 어떤 연습을 하겠나요?\", \"레시피를 읽어도 농도 기준을 모르겠다면 어떻게 배우겠나요?\", \"교육 담당자가 바뀌어 설명 방식이 달라지면 어떻게 내용을 정리하겠나요?\", \"한 번 배운 테이블 세팅을 다음 날 기억하지 못하면 어떻게 하겠나요?\", \"신메뉴 교육 시간이 짧다면 어떤 질문부터 확인하겠나요?\", \"동료는 빨리 배우는데 본인은 더디다면 학습 방식을 어떻게 조정하겠나요?\", \"직접 해 볼 기회가 적은 환불 업무는 어떻게 익혀 두겠나요?\", \"교육 자료와 실제 시연이 다르다면 어떤 기준을 확인하겠나요?\", \"새로운 업무를 혼자 수행해도 된다고 판단하는 기준은 무엇인가요?\", \"설명을 듣는 동안 메모할 내용과 직접 연습할 내용을 어떻게 구분하나요?\", \"배운 내용을 오래 기억하기 위해 어떤 복습 습관을 두고 싶나요?\", \"질문하기 전에 스스로 확인할 부분과 바로 물을 부분은 어떻게 나누나요?\", \"교육받은 내용을 잘못 이해했는지 어떻게 확인하겠나요?\", \"실습 중 느린 속도와 정확한 습득 사이에서 무엇을 기준으로 연습하나요?\", \"새로운 업무를 배울 때 먼저 전체 흐름을 보는 이유는 무엇이라고 생각하나요?\", \"학습이 잘되지 않는 원인을 찾으려면 무엇을 돌아봐야 하나요?\", \"업무 설명서를 자신만의 학습 자료로 바꾼다면 어떻게 구성하겠나요?\", \"입사 첫 주에 배운 내용을 다음 주 업무와 어떻게 연결하겠나요?\"]}, {\"name\": \"업무 이해력\", \"questions\": [\"지시받은 일의 목적을 알고 수행 방식이 달라졌던 경험이 있나요?\", \"모호한 요청을 다시 확인해 오해를 막은 경험을 설명해 주세요.\", \"본인 업무가 다음 사람의 작업에 미치는 영향을 알게 된 경험이 있나요?\", \"처음에는 불필요해 보였던 절차의 이유를 이해한 사례를 말해 주세요.\", \"설명에서 빠진 조건을 발견하고 확인했던 경험이 있나요?\", \"전체 작업 흐름을 파악한 뒤 본인 역할이 명확해진 경험을 설명해 주세요.\", \"같은 말이라도 상황에 따라 의미가 달랐던 경험은 무엇인가요?\", \"업무 요청을 잘못 이해했다는 사실을 어떻게 알아챘나요?\", \"다른 사람에게 업무 목적을 설명해 이해를 도운 경험이 있나요?\", \"결과물의 기준을 미리 확인해 재작업을 줄인 경험을 말해 주세요.\", \"매니저가 단체 손님 준비를 하라고만 말한다면 무엇을 확인하겠나요?\", \"주방에서 주문을 잠시 늦춰 달라고 하면 어떤 상황을 파악하겠나요?\", \"테이블을 빨리 정리해 달라는 요청을 받으면 완료 범위를 어떻게 확인하겠나요?\", \"포장 주문의 수령 시간이 바뀌었다면 관련 업무를 어떻게 살펴보겠나요?\", \"특정 재료를 따로 담으라는 주문이 들어오면 어떤 의미인지 확인하겠나요?\", \"예약석을 비워 두라는 지시를 받으면 어떤 조건을 알아야 하겠나요?\", \"같은 메뉴인데 매장 식사와 배달의 포장 구성이 다르면 무엇을 확인하겠나요?\", \"새 할인 행사를 안내받았다면 적용 범위를 어떻게 정리하겠나요?\", \"재고를 확인하라는 요청에서 기준 시점이 빠져 있다면 어떻게 묻겠나요?\", \"메뉴 제공 순서를 바꾸라는 지시가 내려오면 어떤 영향을 먼저 이해하겠나요?\", \"업무 지시를 들었을 때 목적·기한·완료 기준을 어떻게 정리하나요?\", \"지시를 그대로 반복하는 것과 이해한 내용을 설명하는 것은 어떻게 다른가요?\", \"업무의 앞뒤 과정을 알아야 하는 이유는 무엇이라고 생각하나요?\", \"낯선 용어가 포함된 지시를 받았을 때 어떤 방식으로 확인하겠나요?\", \"구체적인 방법이 없는 지시에서 임의로 결정하기 전에 무엇을 확인하나요?\", \"본인 업무와 매장 전체 흐름을 연결해 보려면 무엇을 관찰해야 하나요?\", \"요청자의 기대와 본인의 해석이 같은지 어떻게 확인하겠나요?\", \"예외 상황과 평소 절차를 구분할 때 어떤 정보를 활용하나요?\", \"업무를 제대로 이해했는지 스스로 설명해 본다면 어떤 내용을 포함하겠나요?\", \"처음 맡는 업무의 완료 모습을 파악하기 위해 어떤 질문을 하겠나요?\"]}, {\"name\": \"업무 정확성\", \"questions\": [\"숫자나 수량을 잘못 확인해 실수했던 뒤 무엇을 바꿨나요?\", \"비슷한 항목을 구분해 정확히 처리했던 경험을 설명해 주세요.\", \"여러 단계의 작업에서 누락을 막기 위해 사용한 방법은 무엇인가요?\", \"제출하거나 전달하기 직전에 오류를 발견한 경험이 있나요?\", \"다른 사람의 결과물을 확인하며 오류를 찾아낸 과정을 말해 주세요.\", \"급한 상황에서도 확인 절차를 지켜 실수를 막은 경험이 있나요?\", \"작은 오차가 결과에 영향을 주었던 경험을 설명해 주세요.\", \"체크리스트를 사용하면서 실수가 줄어든 사례를 이야기해 주세요.\", \"같은 실수가 반복되는 원인을 기록으로 찾은 경험이 있나요?\", \"확인했다고 생각했지만 놓친 항목이 있었을 때 어떻게 보완했나요?\", \"비슷한 이름의 메뉴 두 개가 동시에 주문되면 어떻게 구분하겠나요?\", \"포장 봉투 세 개의 내용물이 각각 다르면 무엇과 대조하겠나요?\", \"고객이 주문을 여러 번 수정했다면 최종 내용을 어떻게 확인하겠나요?\", \"현금 결제 중 말을 걸어 받은 금액이 헷갈리면 어떻게 하겠나요?\", \"레시피가 1인분 기준인데 6인분을 준비한다면 계량을 어떻게 확인하겠나요?\", \"배달 주문서와 화면에 표시된 수량이 다르면 어떻게 처리하겠나요?\", \"재고를 세는 도중 물품이 이동했다면 집계 기준을 어떻게 맞추겠나요?\", \"여러 테이블에 같은 메뉴가 나갈 때 제공 대상을 어떻게 확인하겠나요?\", \"예약 인원과 준비된 식기 수가 맞지 않으면 어떤 자료를 대조하겠나요?\", \"결제 취소 뒤 다시 결제했다면 최종 처리 결과를 어떻게 점검하겠나요?\", \"업무를 한 번 더 확인할 때 처음과 다른 방식으로 보는 이유는 무엇인가요?\", \"실수하기 쉬운 항목을 어떤 기준으로 따로 표시하겠나요?\", \"주문을 복창할 때 반드시 포함해야 할 내용은 무엇이라고 생각하나요?\", \"기억에 의존해도 되는 정보와 기록해야 하는 정보는 어떻게 구분하나요?\", \"수량 확인에서 묶음 단위와 낱개 단위가 섞일 때 무엇을 주의하겠나요?\", \"확인 절차가 형식적인 표시로 끝나지 않게 하려면 어떻게 해야 하나요?\", \"업무 정확성을 높이기 위해 작업 공간을 어떻게 정리하겠나요?\", \"오류를 발견했을 때 영향 범위를 어떻게 확인하겠나요?\", \"자신이 자주 틀리는 부분을 관리하려면 어떤 기록이 도움이 될까요?\", \"마지막 확인을 다른 사람에게 부탁할 때 어떤 부분을 구체적으로 요청하겠나요?\"]}, {\"name\": \"업무 속도\", \"questions\": [\"반복 작업에 걸리는 시간을 줄였던 경험을 설명해 주세요.\", \"작업 속도가 느린 원인을 직접 찾아본 경험이 있나요?\", \"필요한 물건을 미리 준비해 시간을 아낀 사례를 말해 주세요.\", \"이동 동선을 바꿔 더 빠르게 일했던 경험이 있나요?\", \"급하게 하다가 오히려 시간이 더 걸렸던 경험에서 무엇을 배웠나요?\", \"숙련된 사람의 동작을 보고 본인 방식을 바꾼 경험을 설명해 주세요.\", \"작업을 묶어서 처리해 효율이 좋아졌던 경험이 있나요?\", \"일정한 속도를 유지하기 위해 본인의 흐름을 조절한 경험을 말해 주세요.\", \"익숙한 작업의 소요 시간을 예상해 맞춰 본 경험이 있나요?\", \"속도를 높인 뒤 결과의 품질을 어떻게 확인했나요?\", \"점심 전 포장 용기 준비가 오래 걸린다면 어떤 동작부터 살펴보겠나요?\", \"음료 제조 때마다 도구를 찾게 된다면 어떻게 배치하겠나요?\", \"테이블 정리 속도가 동료보다 느리다면 무엇을 관찰하겠나요?\", \"창고에 같은 물품을 가지러 여러 번 왕복한다면 어떻게 줄이겠나요?\", \"주문 입력 중 메뉴 찾기에 시간이 걸리면 어떤 연습을 하겠나요?\", \"포장 스티커를 붙이는 단계에서 작업이 밀리면 무엇을 바꿔 보겠나요?\", \"빠르게 움직이려다 식기를 자주 떨어뜨린다면 어떻게 속도를 조절하겠나요?\", \"손질 작업 시간이 일정하지 않다면 어떤 조건을 비교하겠나요?\", \"같은 준비 작업을 두 사람이 중복하고 있다면 시간을 어떻게 줄이겠나요?\", \"마감 작업의 소요 시간을 예측하려면 어떤 자료를 쌓겠나요?\", \"빠르게 일한다는 것을 단순히 몸을 빨리 움직이는 것과 어떻게 구분하나요?\", \"속도를 높여도 생략해서는 안 되는 과정은 무엇이라고 생각하나요?\", \"작업 시작 전 준비에 시간을 쓰는 것이 언제 도움이 되나요?\", \"반복 업무를 묶어서 처리할 때 어떤 조건을 확인해야 하나요?\", \"동작을 줄일 수 있는지 확인하려면 자신의 작업을 어떻게 살펴보겠나요?\", \"속도가 빨라졌다는 판단에 재작업 시간도 포함해야 하는 이유는 무엇인가요?\", \"처음 배우는 작업에서 속도 목표는 어떻게 설정하는 것이 좋을까요?\", \"이동을 줄이면서도 통로를 막지 않으려면 무엇을 고려하겠나요?\", \"바쁜 시간과 한가한 시간에 준비 방식을 어떻게 달리하겠나요?\", \"속도를 개선한 방법이 다른 동료에게도 유용한지 어떻게 확인하겠나요?\"]}, {\"name\": \"우선순위 판단\", \"questions\": [\"여러 요청이 겹쳤을 때 처리 순서를 정한 경험을 설명해 주세요.\", \"계획한 일을 멈추고 더 급한 일로 전환했던 경험이 있나요?\", \"먼저 할 일을 잘못 골라 문제가 생겼던 사례를 말해 주세요.\", \"다른 사람과 업무 우선순위가 달랐을 때 어떻게 맞췄나요?\", \"중요하지만 급하지 않은 일을 미루지 않도록 관리한 경험이 있나요?\", \"한정된 시간에 일부 업무를 조정해야 했던 경험을 설명해 주세요.\", \"눈앞의 요청보다 더 큰 영향을 주는 일을 먼저 처리한 경험이 있나요?\", \"긴급해 보였던 요청의 실제 기한을 확인한 경험을 말해 주세요.\", \"처리 순서를 바꾼 이유를 다른 사람에게 설명했던 경험이 있나요?\", \"업무가 밀릴 때 도움을 요청할 대상을 정한 경험을 설명해 주세요.\", \"뜨거운 국물이 통로에 쏟아지고 주문 호출도 울리면 무엇부터 하겠나요?\", \"계산 대기와 음식 제공 요청이 겹치면 어떤 정보를 보고 순서를 정하겠나요?\", \"예약 손님 도착 5분 전 재고 정리 요청을 받으면 어떻게 조율하겠나요?\", \"고객 불만과 단순 추가 주문이 동시에 생기면 어떻게 대응 순서를 정하겠나요?\", \"식재료 입고와 일반 청소가 겹치면 어떤 조건을 먼저 확인하겠나요?\", \"마감 업무 세 가지 중 하나만 먼저 끝낼 수 있다면 무엇으로 판단하겠나요?\", \"주방이 지연된 상태에서 새 주문과 기존 주문 문의가 몰리면 어떻게 나누겠나요?\", \"품절 메뉴 안내와 테이블 장식 수정이 동시에 필요하면 어떻게 하겠나요?\", \"매니저 두 명이 서로 다른 급한 일을 맡기면 어떻게 확인하겠나요?\", \"기다리는 고객이 늘어나는 중 배달 기사도 도착하면 어떤 기준으로 조율하겠나요?\", \"긴급한 일과 중요한 일을 구분할 때 어떤 질문을 스스로 하나요?\", \"먼저 들어온 요청을 항상 먼저 처리하기 어려운 이유는 무엇인가요?\", \"업무 순서를 정할 때 고객 영향 외에 무엇을 고려해야 하나요?\", \"본인이 정한 순서를 바꿔야 한다는 신호는 무엇이라고 생각하나요?\", \"지금 처리하지 않을 업무는 어떤 방식으로 기록하겠나요?\", \"우선순위를 바꿀 때 영향을 받는 동료에게 무엇을 알려야 하나요?\", \"판단에 필요한 정보가 부족할 때 어떤 내용을 먼저 확인하나요?\", \"위생이나 안전 문제가 다른 업무보다 앞서는 상황을 어떻게 알아보겠나요?\", \"맡은 일이 모두 급하다고 느껴질 때 어떻게 판단을 정리하겠나요?\", \"하루가 끝난 뒤 본인의 우선순위 판단을 어떻게 돌아보겠나요?\"]}, {\"name\": \"멀티태스킹\", \"questions\": [\"두 가지 이상의 업무를 번갈아 처리했던 방법을 설명해 주세요.\", \"하던 일을 잠시 멈춘 뒤 정확히 이어 갔던 경험이 있나요?\", \"여러 작업의 대기 시간을 활용했던 경험을 말해 주세요.\", \"동시에 받은 요청 중 하나를 잊었을 때 어떤 관리 방식을 만들었나요?\", \"작업별 진행 상태를 눈에 보이게 관리했던 경험이 있나요?\", \"다른 사람의 질문 때문에 집중이 끊겼을 때 어떻게 복귀했나요?\", \"함께 처리할 수 없는 업무를 분리했던 경험을 설명해 주세요.\", \"여러 마감 시간을 동시에 관리했던 방법은 무엇인가요?\", \"알림이나 타이머를 활용해 빠뜨릴 일을 줄인 경험이 있나요?\", \"처리 중인 업무가 너무 많아 일부를 넘겼던 경험을 말해 주세요.\", \"차가 우러나는 동안 포장 주문을 준비한다면 시간을 어떻게 관리하겠나요?\", \"주문 입력 도중 전화가 오면 입력 상태를 어떻게 남기겠나요?\", \"세 테이블의 추가 요청을 연달아 받으면 각각 어떻게 기억하겠나요?\", \"식기세척기 작동 중 다른 일을 맡으면 완료 여부를 어떻게 확인하겠나요?\", \"음료 두 종류의 제조 시간이 다르면 어떤 순서로 전환하겠나요?\", \"결제 중 다른 직원이 질문하면 결제 흐름을 어떻게 보호하겠나요?\", \"포장 작업을 중단하고 손님을 안내한 뒤 무엇부터 확인하겠나요?\", \"예약 전화 내용을 적는 중 현장 고객이 말을 걸면 어떻게 조율하겠나요?\", \"여러 주문의 준비 상태가 섞이기 시작하면 어떤 표시를 사용하겠나요?\", \"타이머가 여러 개 울리는데 각각 무엇인지 모르면 어떻게 정리하겠나요?\", \"동시에 수행할 수 있는 일과 순서대로 해야 하는 일은 어떻게 구분하나요?\", \"업무를 전환하기 직전에 남겨야 할 정보는 무엇이라고 생각하나요?\", \"처리 중인 업무가 본인의 관리 범위를 넘었는지 어떻게 알아차리나요?\", \"여러 요청을 기억하는 데 개인 메모와 공용 화면을 어떻게 활용하겠나요?\", \"대기 시간을 활용할 때 원래 작업으로 복귀하는 시점을 어떻게 정하나요?\", \"중간에 멈추면 오류 위험이 커지는 업무에는 어떤 대응이 필요할까요?\", \"업무를 자주 바꾸면서 생기는 시간 손실을 어떻게 줄이겠나요?\", \"완료한 일과 진행 중인 일을 혼동하지 않으려면 어떤 표시가 좋을까요?\", \"도움을 받아 일부 업무를 넘길 때 남은 작업 상태를 어떻게 설명하겠나요?\", \"바쁜 시간 이후 누락된 요청이 없는지 어떤 순서로 점검하겠나요?\"]}, {\"name\": \"문제 해결력\", \"questions\": [\"예상하지 못한 문제가 생겼을 때 원인을 찾아 해결한 경험을 설명해 주세요.\", \"처음 생각한 원인이 틀렸음을 발견했던 경험이 있나요?\", \"해결책을 여러 개 비교해 선택했던 과정을 말해 주세요.\", \"임시 조치를 한 뒤 근본 원인을 따로 해결했던 경험이 있나요?\", \"사용할 수 있는 자원이 부족할 때 대안을 찾은 경험을 설명해 주세요.\", \"반복되는 문제에서 공통 조건을 찾아낸 경험이 있나요?\", \"혼자 해결하기 어려워 필요한 도움을 구했던 과정을 말해 주세요.\", \"해결을 시도했지만 효과가 없어서 방향을 바꾼 경험이 있나요?\", \"다른 사람의 설명을 듣고 문제를 새롭게 이해했던 경험을 설명해 주세요.\", \"해결 후 문제가 다시 생기지 않는지 확인했던 방법은 무엇인가요?\", \"주문 전표가 출력되지 않으면 어떤 순서로 상태를 확인하겠나요?\", \"특정 음료만 평소보다 맛이 다르다는 의견이 나오면 무엇을 살펴보겠나요?\", \"예약 명단에 고객 이름이 없는데 확인 문자가 있다면 어떻게 해결하겠나요?\", \"포장 용기가 부족하고 추가 주문이 들어오면 어떤 대안을 검토하겠나요?\", \"같은 메뉴의 누락이 반복되면 어떤 과정을 추적하겠나요?\", \"카드 결제가 실패했는데 승인 문자가 왔다면 무엇을 확인하겠나요?\", \"냉장고 문이 제대로 닫히지 않으면 당장 어떤 조치를 하고 누구에게 알리겠나요?\", \"배달 주문 주소가 불명확하고 연락이 안 되면 어떻게 대응하겠나요?\", \"대기 안내 시간과 실제 입장 시간이 계속 어긋나면 무엇을 분석하겠나요?\", \"재고 수량이 매일 일정하게 부족하다면 어떤 자료를 비교하겠나요?\", \"문제를 해결하기 전에 현상을 구체적으로 설명해야 하는 이유는 무엇인가요?\", \"원인에 대한 추측을 확인하려면 어떤 증거가 필요하다고 생각하나요?\", \"해결책을 고를 때 비용과 시간 외에 어떤 영향을 살펴보나요?\", \"임시로 해결한 문제를 그대로 두지 않으려면 무엇을 기록해야 하나요?\", \"직접 시도할 수 있는 조치와 담당자에게 넘길 조치는 어떻게 구분하나요?\", \"해결 과정에서 고객에게 어느 범위까지 설명하는 것이 좋을까요?\", \"문제가 사람의 실수인지 업무 구조 때문인지 어떻게 살펴보겠나요?\", \"이전 해결 방법을 다시 적용하기 전에 무엇을 확인하겠나요?\", \"해결 여부를 판단할 수 있는 결과는 어떻게 정하나요?\", \"본인이 해결한 사례를 팀에 공유한다면 어떤 순서로 설명하겠나요?\"]}, {\"name\": \"협동심\", \"questions\": [\"본인 일을 마친 뒤 동료의 업무를 도왔던 경험을 설명해 주세요.\", \"팀에서 역할을 나누어 공동 결과를 만든 경험이 있나요?\", \"도움을 받는 입장에서 협업이 잘되도록 했던 행동을 말해 주세요.\", \"혼자 처리하던 일을 함께하도록 바꿔 성과가 좋아진 경험이 있나요?\", \"동료의 업무량을 보고 역할을 조정했던 경험을 설명해 주세요.\", \"본인이 선호하지 않는 역할을 팀을 위해 맡은 경험이 있나요?\", \"함께 일하는 사람의 방식에 맞춰 협업했던 과정을 말해 주세요.\", \"역할이 겹쳐 혼선이 생겼을 때 팀에서 어떻게 정리했나요?\", \"공동 작업의 성과를 다른 사람과 나누어 설명했던 경험이 있나요?\", \"팀원 한 명이 빠진 상황에서 업무를 다시 배분했던 경험을 말해 주세요.\", \"본인 구역은 한가하고 옆 구역은 밀려 있다면 어떻게 지원하겠나요?\", \"주방은 음식이 준비됐는데 홀 인력이 부족하면 어떻게 협조하겠나요?\", \"단체 주문을 세 명이 포장해야 한다면 역할을 어떻게 나누겠나요?\", \"동료를 도우려는데 본인 담당 업무도 남았다면 어떻게 조율하겠나요?\", \"신규 직원이 느려서 팀 전체가 지연될 때 어떤 도움을 주겠나요?\", \"마감 업무가 한 사람에게 몰리는 날이라면 어떻게 분담을 제안하겠나요?\", \"동료가 도움을 요청했지만 필요한 지원이 불명확하면 무엇을 묻겠나요?\", \"두 사람이 같은 테이블을 정리하려고 모였다면 어떻게 역할을 나누겠나요?\", \"교대 인원이 줄어드는 날 개점 준비를 어떻게 함께 계획하겠나요?\", \"본인이 지원한 업무가 끝났다면 원래 담당자에게 무엇을 전달하겠나요?\", \"팀을 돕는 행동과 다른 사람의 역할을 무단으로 가져오는 행동은 어떻게 다른가요?\", \"공동 업무에서 역할 분담을 명확히 해야 하는 이유는 무엇인가요?\", \"동료의 도움이 필요한 시점을 어떻게 판단하나요?\", \"도움을 요청할 때 상대가 바로 움직일 수 있도록 무엇을 설명하겠나요?\", \"팀 전체 업무가 잘되고 있는지 보려면 어떤 신호를 관찰해야 하나요?\", \"자신의 작업 성과와 팀의 성과가 다를 때 무엇을 돌아보겠나요?\", \"도와준 동료에게 감사 표시 외에 어떤 후속 행동이 필요할까요?\", \"특정 직원에게 지원이 반복적으로 몰리면 팀에서 무엇을 논의해야 하나요?\", \"경험 차이가 큰 직원끼리 협업할 때 역할을 어떻게 정하면 좋을까요?\", \"함께 일하기 편한 동료가 되기 위해 본인이 실천할 행동은 무엇인가요?\"]}, {\"name\": \"의사소통 능력\", \"questions\": [\"복잡한 내용을 짧고 명확하게 전달했던 경험을 설명해 주세요.\", \"상대가 본인의 말을 다르게 이해했을 때 어떻게 바로잡았나요?\", \"설명을 듣고 핵심 내용을 다시 확인했던 경험이 있나요?\", \"바쁜 사람에게 필요한 정보만 골라 전달했던 방법을 말해 주세요.\", \"말로 전달하기 어려운 내용을 메모로 정리한 경험이 있나요?\", \"서로 다른 용어를 사용해 혼선이 생겼던 일을 어떻게 해결했나요?\", \"중요한 정보를 전달했지만 상대가 못 들었을 때 어떻게 확인했나요?\", \"여러 사람에게 같은 내용을 빠짐없이 공유했던 경험을 설명해 주세요.\", \"상대의 설명을 끝까지 듣고 질문을 바꾼 경험이 있나요?\", \"인계 내용을 정리해 다음 사람이 바로 이해하게 한 경험을 말해 주세요.\", \"소음이 큰 주방에 주문 변경을 전달한다면 어떤 방식으로 확인하겠나요?\", \"고객이 여러 요청을 한꺼번에 말하면 내용을 어떻게 정리해 되묻겠나요?\", \"매니저에게 재고 부족을 짧게 보고한다면 어떤 순서로 말하겠나요?\", \"전화로 예약을 받을 때 잘못 들은 이름과 시간을 어떻게 확인하겠나요?\", \"인계 시간이 짧다면 다음 직원에게 어떤 정보부터 전달하겠나요?\", \"채팅방에 메뉴 품절을 알린다면 어떤 내용을 포함하겠나요?\", \"동료가 애매하게 '저쪽 손님'이라고 말하면 어떻게 대상을 확인하겠나요?\", \"고객에게 조리 지연을 설명할 때 어떤 표현을 사용하겠나요?\", \"한 직원에게 전달한 변경사항을 다른 직원도 알아야 한다면 어떻게 공유하겠나요?\", \"외식업 용어에 익숙하지 않은 신규 직원에게 어떻게 설명하겠나요?\", \"보고할 때 결론을 먼저 말하는 것이 도움이 되는 상황은 무엇인가요?\", \"상대가 이해했는지 확인하려면 어떤 질문을 하는 것이 좋을까요?\", \"구두 전달과 기록 전달은 어떤 기준으로 나누나요?\", \"긴급한 정보가 일반 대화에 묻히지 않게 하려면 어떻게 전달하겠나요?\", \"질문할 때 상대가 답하기 쉽도록 어떤 배경을 제공해야 하나요?\", \"본인의 의견과 확정된 결정을 어떻게 구분해서 말하겠나요?\", \"고객에게 설명할 때 직원끼리 쓰는 표현을 바꿔야 하는 이유는 무엇인가요?\", \"듣는 도중 답을 미리 정하지 않기 위해 어떤 태도가 필요할까요?\", \"여러 사람이 있는 자리에서 전달 대상을 분명히 하는 방법은 무엇인가요?\", \"업무 인계 문장을 간결하게 만들려면 어떤 내용을 남기고 덜어내겠나요?\"]}, {\"name\": \"배려심\", \"questions\": [\"다른 사람이 말하기 전에 불편을 알아차리고 도운 경험을 설명해 주세요.\", \"공동 공간을 다음 사람이 쓰기 편하게 정리했던 경험이 있나요?\", \"도움을 주려다 상대에게 부담이 될 수 있음을 알게 된 경험을 말해 주세요.\", \"처음 온 사람이 소외되지 않도록 행동했던 경험이 있나요?\", \"동료가 쉬는 시간을 방해하지 않으려고 조정한 경험을 설명해 주세요.\", \"다른 사람의 작업 환경을 생각해 본인 행동을 바꾼 경험이 있나요?\", \"상대가 도움을 원하지 않을 때 그 의사를 존중한 경험을 말해 주세요.\", \"잘 드러나지 않는 보조 역할의 수고를 알아본 경험이 있나요?\", \"공용 물품을 사용한 뒤 다음 사용자를 위해 챙긴 경험을 설명해 주세요.\", \"본인의 편의가 다른 사람에게 불편을 주었던 일을 어떻게 수정했나요?\", \"동료가 양손에 식기를 들고 좁은 문을 지나려 하면 어떻게 돕겠나요?\", \"신규 직원이 직원용 물품 위치를 몰라 망설이면 어떻게 안내하겠나요?\", \"퇴근할 동료에게 추가 요청을 해야 한다면 어떤 점을 배려하겠나요?\", \"공용 펜과 메모지를 모두 사용했다면 다음 사람을 위해 무엇을 하겠나요?\", \"손님이 대화를 나누는 옆에서 식기를 정리할 때 어떻게 움직이겠나요?\", \"동료가 설명을 따라오기 힘들어 보이면 어떤 방식으로 도움을 제안하겠나요?\", \"테이블 사이에 고객의 짐이 놓여 있다면 어떻게 통로를 확보하겠나요?\", \"휴게 공간에 본인의 물건이 많이 쌓였다면 어떻게 정리하겠나요?\", \"무거운 상자를 나르는 동료에게 도움을 주기 전에 무엇을 확인하겠나요?\", \"동료의 실수를 손님 앞에서 발견했다면 어떤 장소와 말투로 알리겠나요?\", \"상대가 필요로 하는 도움과 본인이 주고 싶은 도움을 어떻게 구분하나요?\", \"공동 물품을 돌려놓는 위치까지 신경 써야 하는 이유는 무엇인가요?\", \"배려를 이유로 상대의 선택을 대신하지 않으려면 어떻게 해야 하나요?\", \"동료에게 부탁할 때 상대의 업무 흐름을 어떻게 살펴보겠나요?\", \"도움을 받기 어려워하는 사람에게 부담 없이 제안하는 방법은 무엇인가요?\", \"고객 공간에서 소리와 움직임을 조절할 때 무엇을 고려하겠나요?\", \"배려가 특정 동료에게만 집중되지 않게 하려면 어떤 태도가 필요할까요?\", \"본인에게 사소한 일이 다른 사람에게는 큰 불편일 수 있음을 어떻게 확인하나요?\", \"다음 교대자의 입장에서 매장을 살펴본다면 무엇부터 보겠나요?\", \"바쁜 상황에서도 유지할 수 있는 작은 배려 행동을 설명해 주세요.\"]}, {\"name\": \"피드백 수용성\", \"questions\": [\"지적을 받고 실제 업무 방식을 바꾼 경험을 설명해 주세요.\", \"처음에는 동의하기 어려웠던 조언을 다시 검토한 경험이 있나요?\", \"추상적인 피드백을 구체적인 행동으로 바꿨던 방법을 말해 주세요.\", \"같은 지적을 반복해서 받은 뒤 무엇을 다르게 시도했나요?\", \"잘한 점에 대한 피드백을 이후 업무에 활용한 경험이 있나요?\", \"피드백의 이유를 질문해 더 정확히 이해했던 경험을 설명해 주세요.\", \"서로 다른 사람에게 상반된 조언을 받았을 때 어떻게 판단했나요?\", \"지적받은 직후 감정을 가라앉히고 내용을 살펴본 경험이 있나요?\", \"수정한 행동이 나아졌는지 다시 확인을 요청한 경험을 말해 주세요.\", \"본인이 먼저 조언을 구해서 부족한 점을 발견한 경험이 있나요?\", \"매니저가 응대가 딱딱하다고 말하면 어떤 사례를 확인하겠나요?\", \"음식 놓는 위치를 고치라는 지적을 받으면 다음 제공 때 어떻게 반영하겠나요?\", \"바쁜 순간에 동료가 작업 순서를 지적하면 어떻게 듣고 확인하겠나요?\", \"고객이 설명이 부족했다고 남긴 후기를 보면 무엇을 돌아보겠나요?\", \"두 선배가 서로 다른 세팅 방법을 권하면 어떤 기준을 확인하겠나요?\", \"고쳤다고 생각한 행동을 다시 지적받으면 어떻게 점검하겠나요?\", \"지적 내용 중 사실과 다른 부분이 있다면 어떤 방식으로 설명하겠나요?\", \"'더 신경 써 달라'는 말만 들었다면 어떻게 구체화하겠나요?\", \"교육 후 개선 여부를 확인받을 기회가 없다면 어떻게 요청하겠나요?\", \"여러 개선점을 한꺼번에 전달받으면 무엇부터 실행하겠나요?\", \"피드백을 들을 때 즉시 해명하고 싶은 마음을 어떻게 다루겠나요?\", \"조언을 수용한다는 것을 단순히 알겠다고 답하는 것과 어떻게 구분하나요?\", \"지적 내용을 기록한다면 어떤 항목을 남기겠나요?\", \"피드백을 요청하기 좋은 시점과 방식은 무엇이라고 생각하나요?\", \"전달 방식이 불편해도 유용한 내용을 살펴보려면 어떻게 해야 하나요?\", \"모든 조언을 그대로 적용하기 전에 어떤 점을 확인해야 하나요?\", \"개선한 행동이 습관으로 자리 잡도록 무엇을 반복하겠나요?\", \"본인의 의도와 상대가 본 결과가 다를 때 무엇을 중심으로 대화하겠나요?\", \"피드백을 준 사람에게 후속 결과를 알려 주면 어떤 도움이 될까요?\", \"입사 초기 본인에게 가장 자주 확인받고 싶은 업무는 무엇이며 이유는 무엇인가요?\"]}, {\"name\": \"갈등 해결 능력\", \"questions\": [\"함께 일하는 사람과 의견이 달랐던 일을 어떻게 해결했나요?\", \"감정적인 말이 오간 뒤 대화를 다시 시작했던 경험이 있나요?\", \"서로의 오해를 확인하면서 갈등이 풀린 경험을 설명해 주세요.\", \"역할 분담에 대한 불만을 직접 이야기했던 경험이 있나요?\", \"본인의 요구를 조정해 합의점을 찾았던 과정을 말해 주세요.\", \"당사자끼리 해결이 어려워 중재를 요청했던 경험이 있나요?\", \"갈등 상황에서 상대의 입장을 확인하기 위해 어떤 질문을 했나요?\", \"합의한 내용이 지켜지지 않았을 때 어떻게 다시 논의했나요?\", \"개인적인 불편함과 업무상의 쟁점을 분리했던 경험을 설명해 주세요.\", \"갈등이 끝난 뒤 다시 협업 관계를 만든 경험을 말해 주세요.\", \"동료가 힘든 일을 본인에게만 맡긴다고 느껴지면 어떻게 대화하겠나요?\", \"두 직원이 테이블 배정 문제로 언성을 높이면 어떤 방식으로 개입하겠나요?\", \"주문 누락 원인을 두고 홀과 주방이 서로 탓하면 어떻게 쟁점을 정리하겠나요?\", \"동료가 본인의 말을 무시했다고 느껴지면 무엇부터 확인하겠나요?\", \"청소 구역 분담에 동의하지 않는 직원이 있다면 어떻게 합의를 찾겠나요?\", \"고객 앞에서 동료와 의견이 충돌하면 대화를 어떻게 이어 가겠나요?\", \"본인에 대한 불만을 제삼자에게 들었다면 어떻게 당사자와 확인하겠나요?\", \"서로 다른 작업 방식을 고집하는 동료와 함께 일한다면 무엇을 기준으로 정하겠나요?\", \"이전 갈등 때문에 인계가 짧아지고 있다면 어떻게 관계를 회복하겠나요?\", \"반복되는 말다툼이 매장 운영에 영향을 준다면 어떤 도움을 요청하겠나요?\", \"갈등을 이야기할 때 상대의 성격보다 행동을 말해야 하는 이유는 무엇인가요?\", \"대화를 잠시 멈춰야 하는 시점은 어떻게 판단하나요?\", \"상대의 의견을 이해하는 것과 모두 동의하는 것은 어떻게 다른가요?\", \"갈등 해결을 위한 대화 장소와 시간은 어떤 기준으로 정하겠나요?\", \"양쪽 의견을 정리할 때 공통 목표를 찾는 방법은 무엇인가요?\", \"타협할 수 있는 부분과 지켜야 할 기준을 어떻게 구분하나요?\", \"중재자에게 도움을 요청할 때 어떤 사실을 정리해 전달하겠나요?\", \"합의가 말로 끝나지 않도록 어떤 후속 약속을 정해야 하나요?\", \"갈등이 해결됐는지 판단할 때 업무에서 무엇을 관찰하겠나요?\", \"본인이 갈등을 키운 부분을 발견했다면 어떻게 인정하고 수정하겠나요?\"]}, {\"name\": \"친절함\", \"questions\": [\"처음 만난 사람에게 편안한 첫인상을 주려고 노력했던 경험을 말해 주세요.\", \"바쁜 상황에서도 인사를 빠뜨리지 않았던 경험을 설명해 주세요.\", \"상대가 알아듣기 쉽게 말투를 바꿔 안내했던 경험이 있나요?\", \"같은 설명을 여러 번 해야 했을 때 어떻게 응대했나요?\", \"무뚝뚝하다는 말을 들었다면 이후 어떤 행동을 바꿨나요?\", \"부탁을 들어줄 수 없을 때 정중하게 설명했던 경험을 말해 주세요.\", \"자신의 표정이나 목소리가 상대의 반응을 바꾼 경험이 있나요?\", \"기다리던 사람에게 먼저 말을 건넸던 상황을 설명해 주세요.\", \"대화를 마무리할 때 좋은 인상을 남기려 했던 경험을 말해 주세요.\", \"업무에 익숙하지 않아도 밝게 응대하려고 노력한 사례가 있나요?\", \"손님이 들어왔지만 손에 뜨거운 그릇을 들고 있다면 어떻게 맞이하겠나요?\", \"주문 방법을 세 번 물어보는 손님에게 어떻게 설명하겠나요?\", \"마감 시간이 지나 주문을 받을 수 없다면 어떤 말로 안내하겠나요?\", \"바쁜 직원을 불러 미안하다는 손님에게 어떻게 답하겠나요?\", \"손님이 인사에 반응하지 않아도 이후 어떻게 응대하겠나요?\", \"전화로 메뉴를 천천히 읽어 달라는 요청을 받으면 어떻게 하겠나요?\", \"직원끼리 대화하던 중 손님과 눈이 마주치면 어떻게 행동하겠나요?\", \"포장 손님이 이름을 잘못 말해 주문을 찾기 어렵다면 어떻게 묻겠나요?\", \"음식을 건넬 때 주의사항을 부드럽게 전달하려면 어떻게 말하겠나요?\", \"계산을 마친 손님이 출입문을 찾지 못하면 어떻게 안내하겠나요?\", \"친절한 응대가 과도한 친근함이 되지 않도록 어떤 선을 지키겠나요?\", \"짧은 인사에도 진심이 전달되려면 무엇이 중요하다고 생각하나요?\", \"손님 앞에서 피하고 싶은 말투나 표현은 무엇인가요?\", \"직원의 목소리 크기는 어떤 상황에 맞춰 조절해야 하나요?\", \"정중한 거절을 할 때 설명에 어떤 내용을 담아야 하나요?\", \"바쁜 시간의 친절함을 유지하기 위해 어떤 기본 행동을 정하겠나요?\", \"손님에게 먼저 말을 걸지 않는 편이 좋은 때는 언제라고 생각하나요?\", \"전화 응대와 대면 응대에서 친절을 표현하는 방법은 어떻게 다른가요?\", \"익숙한 단골과 처음 온 손님을 응대할 때 어떤 기준을 같게 유지하겠나요?\", \"자신의 응대가 편안했는지 어떤 반응을 보고 돌아보겠나요?\"]}, {\"name\": \"공감 능력\", \"questions\": [\"상대의 말을 끝까지 듣고 처음 판단을 바꾼 경험을 설명해 주세요.\", \"본인에게 사소한 일이 상대에게 중요했던 경험이 있나요?\", \"불편을 말하지 못하는 사람의 마음을 확인했던 경험을 말해 주세요.\", \"상대의 입장을 이해한 뒤 해결 방향이 달라진 경험이 있나요?\", \"다른 사람의 실망을 인정하면서 대화를 이어 간 경험을 설명해 주세요.\", \"조언보다 경청이 더 도움이 되었던 상황을 말해 주세요.\", \"본인의 경험을 기준으로 상대를 판단했다가 수정한 적이 있나요?\", \"화난 말 속에서 실제 요구를 찾아냈던 경험을 설명해 주세요.\", \"상대가 원하는 도움을 직접 물어보고 제공한 경험이 있나요?\", \"같은 상황을 서로 다르게 받아들인 이유를 이해한 경험을 말해 주세요.\", \"오래 기다린 손님이 시간이 아깝다고 말하면 무엇부터 확인하겠나요?\", \"기념일 식사가 기대와 달랐다는 손님에게 어떻게 대화를 시작하겠나요?\", \"음식 양이 적다며 실망한 손님에게 어떤 질문을 하겠나요?\", \"일행 앞에서 주문 실수를 지적받아 당황한 손님을 어떻게 응대하겠나요?\", \"메뉴를 고르지 못해 조급해하는 손님에게 어떤 도움을 제안하겠나요?\", \"대기 순서가 공정하지 않다고 느끼는 손님의 말을 어떻게 듣겠나요?\", \"바쁜 직원에게 요청하기 어렵다는 손님에게 어떻게 답하겠나요?\", \"동료가 사소한 지적에도 위축된 모습을 보이면 어떻게 말을 걸겠나요?\", \"손님이 원하는 해결책과 본인이 예상한 해결책이 다르면 어떻게 하겠나요?\", \"함께 온 두 손님의 불편이 서로 다르다면 어떻게 각각 확인하겠나요?\", \"상대의 감정을 이해하는 것과 요구를 모두 수용하는 것은 어떻게 다른가요?\", \"공감하는 말을 건넬 때 피해야 할 단정은 무엇이라고 생각하나요?\", \"손님의 불편을 정확히 이해했는지 어떤 말로 확인하겠나요?\", \"본인이 겪어 보지 않은 불편에도 공감하려면 무엇이 필요한가요?\", \"문제 설명보다 감정 표현이 길어질 때 어떤 태도로 듣겠나요?\", \"상대를 위로하려다 불편을 가볍게 만들지 않으려면 무엇을 주의하겠나요?\", \"말로 표현한 요구와 실제 기대가 다를 때 무엇을 더 물어보겠나요?\", \"공감 표현 뒤에 실질적인 도움을 연결하려면 어떤 순서가 좋을까요?\", \"사람마다 다른 기대를 존중하면서 매장 기준을 어떻게 설명하겠나요?\", \"대화를 마친 뒤 상대가 이해받았다고 느꼈는지 무엇으로 살펴보겠나요?\"]}, {\"name\": \"감정 조절 능력\", \"questions\": [\"기분이 좋지 않은 날에도 필요한 응대를 유지했던 경험을 말해 주세요.\", \"억울한 말을 들었을 때 즉시 반박하지 않고 대응한 경험이 있나요?\", \"여러 요청이 몰려 당황했을 때 마음을 가라앉힌 방법은 무엇인가요?\", \"실수한 직후 자책을 멈추고 업무에 복귀했던 경험을 설명해 주세요.\", \"자신의 말투가 거칠어졌음을 알아차리고 조절한 경험이 있나요?\", \"긴장해서 평소 능력을 발휘하기 어려웠던 상황을 어떻게 넘겼나요?\", \"동료에게 화가 났지만 업무 대화를 이어 간 경험을 말해 주세요.\", \"반복되는 불평을 들으면서 감정 소모를 줄였던 방법은 무엇인가요?\", \"감정적으로 대응한 뒤 관계를 회복했던 경험을 설명해 주세요.\", \"스트레스가 쌓이기 전에 도움을 요청했던 경험이 있나요?\", \"손님이 본인 실수가 아닌 일로 큰소리를 내면 먼저 어떻게 행동하겠나요?\", \"주문이 밀려 머리가 하얘질 때 바로 할 수 있는 행동은 무엇인가요?\", \"동료가 손님 앞에서 날카롭게 지적하면 어떻게 반응하겠나요?\", \"불만 응대를 끝낸 직후 다음 손님을 맞아야 한다면 어떻게 전환하겠나요?\", \"같은 실수를 반복해 스스로 화가 난 상태라면 어떻게 업무를 이어 가겠나요?\", \"휴게 전까지 일이 계속 몰려 짜증이 올라오면 어떻게 조절하겠나요?\", \"고객의 모욕적인 발언이 계속된다면 어떤 방식으로 지원을 요청하겠나요?\", \"답답한 마음에 동료에게 퉁명스럽게 말했다면 어떻게 바로잡겠나요?\", \"주변 직원의 조급한 분위기에 휩쓸릴 때 무엇을 하겠나요?\", \"긴장한 상태에서 현금 정산을 해야 한다면 어떻게 집중을 회복하겠나요?\", \"감정이 업무에 영향을 주기 시작했다는 신호는 무엇인가요?\", \"불편한 감정을 숨기는 것과 조절하는 것은 어떻게 다르다고 생각하나요?\", \"응대 중 잠시 다른 직원의 도움을 받아야 할 기준은 무엇인가요?\", \"화가 났을 때 바로 하지 않기로 정한 행동이 있나요?\", \"개인 감정과 업무 판단을 분리하기 위해 어떤 질문을 스스로 하겠나요?\", \"긴장을 낮추는 방법 중 근무 현장에서 사용할 수 있는 것은 무엇인가요?\", \"감정이 격해진 동료와 일할 때 본인의 반응을 어떻게 관리하겠나요?\", \"불만 응대 후 다음 업무에 감정을 남기지 않으려면 무엇이 필요한가요?\", \"감정을 조절하면서도 부당한 언행에 경계를 세우려면 어떻게 말하겠나요?\", \"하루를 마친 뒤 감정적으로 어려웠던 응대를 어떤 방식으로 돌아보겠나요?\"]}, {\"name\": \"서비스 감각\", \"questions\": [\"요청받기 전에 필요한 물품을 준비해 도움이 된 경험을 말해 주세요.\", \"상대의 행동을 보고 안내 시점을 조절했던 경험이 있나요?\", \"좋은 의도로 제공한 도움이 오히려 방해가 되었던 경험을 설명해 주세요.\", \"여러 사람의 이용 속도에 맞춰 진행을 조절한 경험을 말해 주세요.\", \"작은 불편을 발견해 전체 경험을 편하게 만든 사례가 있나요?\", \"상대가 원하는 서비스 수준을 확인하고 조정했던 경험을 설명해 주세요.\", \"공간이나 물건의 배치를 바꿔 이용을 편리하게 한 경험이 있나요?\", \"안내를 너무 늦게 해서 아쉬웠던 경험과 이후 바꾼 점은 무엇인가요?\", \"메뉴나 상품을 상황에 맞게 추천했던 경험을 말해 주세요.\", \"이용이 끝날 때까지 흐름을 살펴 후속 도움을 제공한 경험이 있나요?\", \"손님들이 빈 물병을 번갈아 보고 있다면 어떤 방식으로 다가가겠나요?\", \"대화에 집중한 테이블의 접시를 치울 시점은 어떻게 판단하겠나요?\", \"한 사람의 음식만 늦어지는 테이블에는 어떤 안내가 필요하겠나요?\", \"큰 짐을 든 손님이 좁은 통로에 서 있다면 어떻게 돕겠나요?\", \"포장 음식이 준비됐는데 손님이 전화 중이라면 어떻게 전달하겠나요?\", \"메뉴판을 오래 살피는 손님에게 어떤 질문으로 추천을 시작하겠나요?\", \"손님이 계산대를 찾는 듯 주변을 살피면 어떻게 확인하겠나요?\", \"식사 중 식기가 바닥에 떨어진 것을 보면 어떤 순서로 대응하겠나요?\", \"단체 손님의 음식 도착 간격이 길어질 때 무엇을 살피겠나요?\", \"손님이 남은 음식을 포장하려는 듯 보이면 어떻게 제안하겠나요?\", \"먼저 돕는 서비스와 불필요한 개입을 가르는 기준은 무엇인가요?\", \"테이블을 살필 때 손님에게 부담을 주지 않으려면 어떻게 해야 하나요?\", \"주문부터 퇴점까지 불편이 생기기 쉬운 순간은 언제라고 생각하나요?\", \"메뉴 추천에서 매장 판매 목표와 손님 필요를 어떻게 함께 고려하겠나요?\", \"서비스의 적절한 타이밍을 판단할 때 어떤 단서를 보겠나요?\", \"손님의 말없는 신호를 해석할 때 어떤 확인이 필요하다고 생각하나요?\", \"제공하기로 한 서비스가 지연될 때 언제 먼저 안내해야 하나요?\", \"매장 분위기에 맞는 응대 거리를 어떻게 익히겠나요?\", \"작은 요청을 해결한 뒤 추가 확인이 필요한지는 어떻게 판단하겠나요?\", \"손님이 편하게 식사를 마쳤는지 어떤 장면을 통해 돌아보겠나요?\"]}, {\"name\": \"위생 관념\", \"questions\": [\"손 씻기가 필요한 상황을 알아차려 작업을 멈춘 경험을 말해 주세요.\", \"날것과 바로 먹는 식품을 구분해 다뤘던 경험이 있나요?\", \"보관 상태가 의심스러운 식품을 발견했을 때 어떻게 했나요?\", \"겉으로 깨끗해 보여도 다시 세척하거나 교체했던 경험을 설명해 주세요.\", \"식품 취급 도구를 용도별로 구분해 사용했던 경험이 있나요?\", \"위생상 우려되는 습관을 고치려고 노력한 경험을 말해 주세요.\", \"식재료의 표시사항을 확인해 사용 여부를 결정한 경험이 있나요?\", \"여러 사람이 함께 먹을 음식을 준비하며 신경 쓴 점은 무엇인가요?\", \"위생 절차를 몰라 담당자에게 확인했던 경험을 설명해 주세요.\", \"오염 가능성을 발견해 다른 사람의 작업을 잠시 멈춘 경험이 있나요?\", \"돈을 만진 직후 포장 식품을 다뤄야 한다면 어떻게 하겠나요?\", \"생고기를 자른 도마에 채소를 올리려는 동료를 보면 어떻게 하겠나요?\", \"냉장 보관 식재료가 작업대에 오래 놓여 있다면 무엇을 확인하겠나요?\", \"장갑을 낀 채 휴대전화를 만졌다면 다음 작업 전에 어떻게 하겠나요?\", \"재료 용기의 개봉일 표시가 없으면 어떻게 처리하겠나요?\", \"음식에 이물질이 들어갔다는 말을 들으면 해당 음식과 주변 재료를 어떻게 하겠나요?\", \"알레르기 관련 요청을 받은 음식의 조리 도구가 섞였다면 어떻게 하겠나요?\", \"식품을 덮은 뚜껑 안쪽이 바닥에 닿았다면 어떻게 처리하겠나요?\", \"세척한 채소 옆에 흙 묻은 상자가 놓여 있다면 무엇을 바꾸겠나요?\", \"냉장고 온도가 매장 관리 기준을 벗어나면 어떤 순서로 대응하겠나요?\", \"장갑 착용만으로 위생이 보장되지 않는 이유는 무엇이라고 생각하나요?\", \"식품의 냄새와 외관만으로 사용 여부를 판단하면 어떤 한계가 있나요?\", \"작업이 바뀔 때 손과 도구의 상태를 어떻게 확인하겠나요?\", \"조리 전후 식품의 동선이 겹치지 않게 하려면 무엇을 살펴야 하나요?\", \"식품 안전에 확신이 없을 때 어떤 기준으로 작업을 멈추겠나요?\", \"알레르기 유발 재료가 다른 음식에 섞이지 않게 무엇을 주의하겠나요?\", \"식재료 입고 시 위생 측면에서 어떤 정보를 확인하겠나요?\", \"위생상 이상을 발견한 사실은 누구에게 어떤 내용으로 알리겠나요?\", \"음식 취급 중 머리카락이나 개인 소지품으로 인한 오염을 어떻게 줄이겠나요?\", \"위생 기준이 기억나지 않을 때 임의로 판단하지 않으려면 어떻게 하겠나요?\"]}, {\"name\": \"청결 유지\", \"questions\": [\"정리되지 않은 공간을 꾸준히 관리했던 경험을 설명해 주세요.\", \"청소 후에도 남은 얼룩을 발견해 다시 처리했던 경험이 있나요?\", \"여러 사람이 쓰는 공간의 청결 기준을 맞춘 경험을 말해 주세요.\", \"눈에 잘 띄지 않는 곳까지 청소했던 사례가 있나요?\", \"청소 도구를 사용 후 관리했던 방법을 설명해 주세요.\", \"바쁜 일정 속에서 청소 시간을 확보했던 경험을 말해 주세요.\", \"청소가 자주 누락되는 구역을 찾아 관리한 경험이 있나요?\", \"물건을 제자리에 두는 습관으로 작업 공간을 개선한 경험을 설명해 주세요.\", \"청소 담당자끼리 완료 기준이 달라 조정했던 경험이 있나요?\", \"냄새나 끈적임의 원인을 찾아 제거했던 경험을 말해 주세요.\", \"손님이 나간 테이블에 얼룩과 부스러기가 함께 남았다면 어떻게 정리하겠나요?\", \"바닥을 닦았는데 발자국이 계속 남는다면 무엇을 점검하겠나요?\", \"쓰레기통이 가득 차기 직전인데 주문이 이어지면 어떻게 관리하겠나요?\", \"냉장고 손잡이에 끈적한 자국이 보이면 어떻게 처리하겠나요?\", \"청소용 천에서 냄새가 나는데 여분이 없다면 어떻게 하겠나요?\", \"테이블 아래 음식물이 손님에게 보이지 않더라도 어떻게 처리하겠나요?\", \"화장실 점검표에는 완료로 적혔지만 오염이 남아 있다면 어떻게 하겠나요?\", \"배수구 주변에 찌꺼기가 쌓이기 시작하면 어떤 작업을 하겠나요?\", \"청소를 위해 옮긴 물품을 어디에 둘지 애매하다면 어떻게 정리하겠나요?\", \"마감 청소 후 다음 날 같은 구역이 더럽다는 말을 들으면 무엇을 확인하겠나요?\", \"청소를 끝냈다는 판단은 어떤 상태를 기준으로 해야 하나요?\", \"영업 중 수시 청소와 마감 청소의 역할은 어떻게 다르다고 생각하나요?\", \"청소 구역별로 도구를 구분하는 이유를 어떻게 설명하겠나요?\", \"오염을 발견했을 때 즉시 처리할 것과 작업 시간을 정할 것을 어떻게 나누겠나요?\", \"정돈된 상태를 오래 유지하려면 물건 배치를 어떻게 정해야 하나요?\", \"청소 담당이 아닌 구역의 오염을 발견하면 어떤 태도로 대응하겠나요?\", \"청소 기록을 남길 때 다음 담당자에게 도움이 되는 정보는 무엇인가요?\", \"손님이 이용 중인 공간을 청소할 때 무엇을 배려해야 하나요?\", \"청소 품질이 사람마다 달라지지 않도록 어떤 기준을 공유하겠나요?\", \"놓치기 쉬운 청소 구역을 정기적으로 확인하려면 어떤 방법을 쓰겠나요?\"]}, {\"name\": \"안전 의식\", \"questions\": [\"사고가 나기 전에 위험 요소를 발견해 조치한 경험을 말해 주세요.\", \"익숙하지 않은 도구를 쓰기 전 사용법을 확인했던 경험이 있나요?\", \"위험한 작업을 혼자 하지 않고 도움을 구했던 경험을 설명해 주세요.\", \"아찔했던 상황을 겪은 뒤 작업 방식을 바꾼 경험이 있나요?\", \"주변 사람에게 위험을 알렸던 경험과 전달 방법을 말해 주세요.\", \"급한 상황에서도 안전 절차를 지켰던 사례가 있나요?\", \"무거운 물건을 옮길 때 이동 경로를 정리했던 경험을 설명해 주세요.\", \"장비 이상을 발견해 사용을 중단한 경험이 있나요?\", \"비상 상황에 대비한 안내나 훈련에 참여했다면 무엇을 배웠나요?\", \"안전 문제를 대수롭지 않게 여기는 사람을 설득한 경험을 말해 주세요.\", \"바닥에 기름이 쏟아졌는데 손님이 다가온다면 무엇부터 하겠나요?\", \"뜨거운 국물을 든 직원과 좁은 통로에서 마주치면 어떻게 하겠나요?\", \"칼이 작업대 가장자리에 놓여 있다면 어떻게 처리하겠나요?\", \"전기 기기에서 타는 냄새가 나면 어떤 순서로 대응하겠나요?\", \"높은 선반의 무거운 상자를 내려야 한다면 어떻게 준비하겠나요?\", \"깨진 유리가 식기 보관 구역에 흩어지면 어떻게 접근을 막고 처리하겠나요?\", \"출입문 앞에 납품 상자가 쌓여 통로를 막으면 어떻게 하겠나요?\", \"사용법을 모르는 세제를 섞어 쓰자는 말을 들으면 어떻게 대응하겠나요?\", \"조리 중 작은 화상을 입은 동료를 보면 어떻게 업무를 조정하고 돕겠나요?\", \"매장 안에서 연기나 화재 징후를 발견하면 무엇을 우선하겠나요?\", \"작업 속도를 높이더라도 생략하면 안 되는 안전 확인은 무엇인가요?\", \"사고 직전 상황을 공유하는 것이 왜 필요하다고 생각하나요?\", \"처음 출근한 매장에서 어떤 비상 시설과 연락 절차를 확인하겠나요?\", \"위험을 발견했지만 직접 제거할 수 없을 때 어떻게 하겠나요?\", \"장비를 사용해도 되는 상태인지 확신이 없으면 어떤 판단을 하겠나요?\", \"미끄러짐이나 충돌을 줄이기 위해 이동할 때 어떤 습관을 두겠나요?\", \"보호 장비가 불편할 때 어떤 방식으로 문제를 해결하겠나요?\", \"손님과 직원이 함께 쓰는 통로에서는 어떤 위험을 살펴야 하나요?\", \"사고 보고에는 추측을 줄이고 어떤 사실을 담아야 하나요?\", \"반복 작업에서 경계심이 낮아지지 않도록 어떤 점검을 하겠나요?\"]}, {\"name\": \"규정 준수\", \"questions\": [\"익숙한 방식과 다른 규칙을 배워 적용했던 경험을 말해 주세요.\", \"규칙의 이유를 이해하기 어려워 담당자에게 물었던 경험이 있나요?\", \"다른 사람이 생략하는 절차를 그대로 지켰던 경험을 설명해 주세요.\", \"본인 권한 밖의 요청을 담당자에게 연결한 경험이 있나요?\", \"변경된 규정을 늦게 알게 되었을 때 어떻게 대응했나요?\", \"예외를 요구하는 상대에게 기준을 설명했던 경험을 말해 주세요.\", \"지시와 문서 내용이 달라 확인했던 경험이 있나요?\", \"절차를 잘못 이해한 사실을 발견하고 수정한 경험을 설명해 주세요.\", \"개인정보나 내부 자료의 취급 기준을 지킨 경험이 있나요?\", \"규정상 필요한 기록을 빠뜨리지 않도록 관리했던 방법은 무엇인가요?\", \"단골이 규정에 없는 할인을 요구하면 어떤 절차로 대응하겠나요?\", \"영수증 없는 환불 요청을 받으면 무엇부터 확인하겠나요?\", \"직원 계정을 빌려 달라는 동료에게 어떻게 답하겠나요?\", \"예약 고객의 연락처를 지인이 물어보면 어떻게 대응하겠나요?\", \"할인과 쿠폰의 중복 적용 기준이 헷갈리면 어떻게 처리하겠나요?\", \"교육받지 않은 장비를 바로 사용하라는 요청을 받으면 어떻게 하겠나요?\", \"매장 공지와 선임의 안내가 서로 다르면 어떤 방식으로 확인하겠나요?\", \"손님이 정해진 대기 순서를 건너뛰게 해 달라고 하면 어떻게 설명하겠나요?\", \"폐기 처리해야 할 상품을 임의로 가져가자는 말을 들으면 어떻게 하겠나요?\", \"결제 취소 후 필요한 승인 기록이 누락됐다면 어떻게 보완하겠나요?\", \"규정을 지키면서도 손님에게 선택 가능한 방법을 어떻게 안내하겠나요?\", \"자주 발생하는 예외 요청은 어떤 방식으로 기록하고 공유하겠나요?\", \"본인에게 허용된 처리 권한은 언제 어떻게 확인하겠나요?\", \"규정이 비효율적으로 느껴질 때 변경 전까지 어떻게 행동하겠나요?\", \"오래된 안내문을 계속 따르지 않으려면 무엇을 확인해야 하나요?\", \"구두로 받은 예외 승인은 어떤 내용까지 확인해 두는 것이 좋을까요?\", \"친한 사람의 요청에도 동일한 기준을 적용해야 하는 이유는 무엇인가요?\", \"고객 정보를 업무 목적으로 다룰 때 어떤 범위를 지키겠나요?\", \"규정 위반을 발견했을 때 사실 확인과 보고를 어떻게 진행하겠나요?\", \"새 규정을 전달받으면 실제 업무에 반영됐는지 어떻게 점검하겠나요?\"]}, {\"name\": \"적응력\", \"questions\": [\"처음 가는 환경에서 역할을 익혔던 과정을 설명해 주세요.\", \"기존에 쓰던 것과 다른 도구나 시스템을 배운 경험이 있나요?\", \"새로운 구성원들과 함께 일하는 방식에 익숙해진 경험을 말해 주세요.\", \"활동 장소가 바뀌어 동선을 다시 익혔던 경험이 있나요?\", \"이전 방식이 통하지 않는 환경에서 습관을 바꾼 경험을 설명해 주세요.\", \"처음에는 낯설었던 업무 용어를 익혔던 방법은 무엇인가요?\", \"새로운 업무 속도에 적응하기 위해 연습한 경험을 말해 주세요.\", \"역할이 바뀐 뒤 가장 먼저 확인했던 사항은 무엇이었나요?\", \"낯선 환경에서 질문할 사람을 찾아 도움받은 경험이 있나요?\", \"적응이 예상보다 오래 걸렸던 일을 어떻게 이어 갔나요?\", \"새 매장의 주방 배치가 이전 경험과 완전히 다르면 어떻게 익히겠나요?\", \"처음 보는 주문 단말기를 사용해야 한다면 어떤 순서로 배우겠나요?\", \"매장마다 쓰는 메뉴 약어가 다르면 어떻게 혼동을 줄이겠나요?\", \"홀 업무를 배우던 중 포장 업무도 맡게 되면 무엇부터 확인하겠나요?\", \"새 매니저가 보고 방식을 바꾸면 어떻게 업무에 반영하겠나요?\", \"새 메뉴가 여러 개 도입되면 기존 메뉴와 구분해 어떻게 익히겠나요?\", \"다른 지점으로 지원 근무를 가면 시작 전에 무엇을 확인하겠나요?\", \"처음 함께 일하는 조와 업무 리듬이 맞지 않으면 어떻게 조정하겠나요?\", \"매장 리모델링으로 물품 위치가 달라지면 어떻게 빠르게 파악하겠나요?\", \"첫 주에 같은 부분에서 계속 막힌다면 어떤 도움을 요청하겠나요?\", \"새로운 환경에 적응할 때 먼저 관찰하는 것은 무엇인가요?\", \"익숙한 경험을 활용할 부분과 새로 배울 부분을 어떻게 구분하나요?\", \"적응 과정에서 모르는 것을 숨기지 않으려면 어떤 태도가 필요한가요?\", \"새 업무를 혼자 수행해도 될 정도로 익혔는지 무엇으로 판단하겠나요?\", \"처음부터 모든 것을 외우기 어려울 때 어떤 정보를 먼저 정리하겠나요?\", \"적응 속도를 비교하며 조급해질 때 어떻게 학습 계획을 세우겠나요?\", \"새 환경의 관행을 배우면서 반드시 확인해야 할 기준은 무엇인가요?\", \"첫 출근 후 한 주 동안 어떤 질문을 모아 두고 싶나요?\", \"잘 적응하고 있다는 피드백은 누구에게 어떤 내용으로 구하겠나요?\", \"새 업무에 익숙해진 뒤 남은 부족한 부분을 어떻게 찾겠나요?\"]}, {\"name\": \"유연성\", \"questions\": [\"준비한 계획이 어긋나 다른 방법으로 목표를 이룬 경험을 말해 주세요.\", \"상대의 제안을 받아들여 본인 방식을 바꾼 경험이 있나요?\", \"사용할 수 있는 자원이 줄어 작업 방식을 조정한 경험을 설명해 주세요.\", \"예상보다 참여 인원이 많거나 적어 진행을 바꾼 경험이 있나요?\", \"처음 선택한 방법을 고집하다가 방향을 수정했던 경험을 말해 주세요.\", \"상황에 따라 설명이나 안내 방식을 달리했던 경험이 있나요?\", \"갑작스러운 요청 변경을 받고 가능한 대안을 제시한 경험을 설명해 주세요.\", \"다른 의견을 비교한 뒤 절충안을 만든 경험이 있나요?\", \"계획 일부를 포기하고 중요한 결과를 지켜 낸 경험을 말해 주세요.\", \"당일 여건에 맞춰 역할을 바꿨던 경험과 그 이유는 무엇인가요?\", \"예약 인원이 현장에서 늘어났다면 좌석 운영을 어떻게 조정하겠나요?\", \"손님이 주문 후 구성 변경을 원하면 무엇을 확인해 대안을 찾겠나요?\", \"포장 용기가 부족할 때 어떤 조건을 확인하고 다른 방법을 제안하겠나요?\", \"비가 와서 야외 좌석을 쓸 수 없다면 안내 방식을 어떻게 바꾸겠나요?\", \"단체 손님의 도착이 늦어지면 준비한 서비스 순서를 어떻게 조정하겠나요?\", \"예정된 재료가 입고되지 않으면 대체 가능 여부를 어떻게 확인하겠나요?\", \"키오스크 이용이 어려운 손님에게 어떤 다른 주문 방법을 안내하겠나요?\", \"배달 주문이 갑자기 늘어 포장 공간이 부족하면 어떻게 운영을 조정하겠나요?\", \"손님이 설명을 잘 듣지 못하는 환경이라면 안내 방법을 어떻게 바꾸겠나요?\", \"임시로 바꾼 방식이 효과가 없으면 언제 어떤 기준으로 다시 수정하겠나요?\", \"상황에 맞게 바꿀 수 있는 것과 유지해야 하는 기준은 어떻게 구분하나요?\", \"대안을 제안하기 전에 어떤 제한 조건을 확인해야 하나요?\", \"본인의 익숙한 방법을 내려놓을 필요가 있다는 신호는 무엇인가요?\", \"변경 사항이 동료에게 혼란을 주지 않으려면 어떻게 공유하겠나요?\", \"손님의 요청을 그대로 수용하기 어려울 때 대안을 어떻게 찾겠나요?\", \"임시 조치가 정식 방식으로 굳어지지 않게 무엇을 기록하겠나요?\", \"새로운 방법을 시험할 때 실패의 영향을 어떻게 줄이겠나요?\", \"갑작스러운 변화에서 선택지가 여러 개라면 무엇을 기준으로 고르겠나요?\", \"방법을 바꾼 뒤 원래 목표를 놓치지 않았는지 어떻게 확인하겠나요?\", \"유연하게 대응하면서도 팀의 합의가 필요한 순간은 언제인가요?\"]}, {\"name\": \"자기주도성\", \"questions\": [\"누가 시키기 전에 필요한 일을 찾아 수행했던 경험을 말해 주세요.\", \"본인에게 부족한 기술을 스스로 연습했던 경험이 있나요?\", \"해야 할 일을 직접 정하고 실행 순서를 세운 경험을 설명해 주세요.\", \"업무 자료를 스스로 찾아 문제를 해결한 경험이 있나요?\", \"주변의 요청 없이 준비물을 미리 마련해 도움이 된 사례를 말해 주세요.\", \"처음 맡은 과제에서 필요한 질문을 정리해 물어본 경험이 있나요?\", \"활동이 잠시 멈춘 시간에 스스로 할 일을 찾았던 경험을 설명해 주세요.\", \"본인 제안으로 시작한 일을 끝까지 운영한 경험이 있나요?\", \"먼저 나섰다가 권한 확인이 필요함을 알게 된 경험을 말해 주세요.\", \"스스로 세운 목표의 진행 상황을 점검했던 방법은 무엇인가요?\", \"담당 구역의 일이 끝났지만 영업은 계속된다면 무엇을 살펴보겠나요?\", \"내일 예약이 많다는 공지를 봤다면 오늘 어떤 준비를 제안하겠나요?\", \"자주 묻는 메뉴 정보를 잘 모른다는 것을 깨달으면 어떻게 익히겠나요?\", \"소모품이 곧 떨어질 것으로 보이는데 담당자가 바쁘면 어떻게 하겠나요?\", \"처음 맡은 마감 업무의 안내가 부족하면 어떤 정보를 먼저 찾겠나요?\", \"동료들이 반복해서 같은 위치를 묻는다면 본인이 할 수 있는 일은 무엇인가요?\", \"손님이 없는 시간에 매니저의 지시가 없다면 어떻게 할 일을 정하겠나요?\", \"자신의 작업 속도가 부족하다고 느끼면 어떤 연습 계획을 세우겠나요?\", \"새 직원이 필요한 자료를 못 찾는 모습을 보면 어떻게 도울 방법을 찾겠나요?\", \"먼저 처리하려던 일이 다른 직원의 담당과 겹치면 어떻게 조율하겠나요?\", \"일을 스스로 찾을 때 가장 먼저 확인하는 정보는 무엇인가요?\", \"주도적으로 행동하는 것과 독단적으로 결정하는 것은 어떻게 다른가요?\", \"시작 전에 승인이 필요한 일은 어떤 기준으로 구분하겠나요?\", \"당장 급하지 않아도 미리 준비할 일은 어떻게 찾아내겠나요?\", \"스스로 정한 학습 목표가 실제 업무에 도움이 되는지 어떻게 확인하겠나요?\", \"질문하기 전에 직접 확인해 볼 내용과 바로 물어볼 내용은 어떻게 나누나요?\", \"먼저 나선 일이 늘어날 때 기존 담당 업무를 어떻게 지키겠나요?\", \"본인이 발견한 일을 제안할 때 상대에게 어떤 정보를 주겠나요?\", \"자율적으로 일할 수 있는 범위를 처음에 어떻게 합의하고 싶나요?\", \"매주 스스로 개선하거나 익힐 한 가지를 어떤 방식으로 정하겠나요?\"]}, {\"name\": \"개선 의지\", \"questions\": [\"반복해서 생기는 문제를 관찰해 원인을 찾은 경험을 말해 주세요.\", \"기존 방식의 불편을 구체적인 제안으로 바꾼 경험이 있나요?\", \"작은 변경을 시험한 뒤 효과를 확인했던 경험을 설명해 주세요.\", \"좋은 아이디어라고 생각했지만 결과가 좋지 않았던 경험이 있나요?\", \"다른 사람의 의견을 받아 개선안을 수정했던 경험을 말해 주세요.\", \"물건 위치나 작업 순서를 바꿔 낭비를 줄인 경험이 있나요?\", \"같은 실수가 반복되지 않도록 안내를 바꾼 경험을 설명해 주세요.\", \"개선 전후를 비교하기 위해 기록했던 정보는 무엇인가요?\", \"바꾼 방식이 오래 유지되도록 도왔던 경험을 말해 주세요.\", \"제안이 받아들여지지 않았을 때 이후 어떻게 행동했나요?\", \"포장 주문에서 같은 상품이 자주 빠진다면 원인을 어떻게 찾겠나요?\", \"직원들이 소스를 찾느라 매번 돌아다닌다면 무엇부터 관찰하겠나요?\", \"손님이 메뉴판의 같은 부분을 반복해서 오해하면 어떤 개선을 제안하겠나요?\", \"식재료 폐기가 특정 요일에 많다면 어떤 자료를 확인하겠나요?\", \"마감 청소가 늘 늦어지면 어떤 과정을 나눠 살펴보겠나요?\", \"결제 대기가 길지만 원인이 분명하지 않다면 어떻게 조사하겠나요?\", \"개선안을 적용했더니 다른 구역의 일이 늘었다면 어떻게 수정하겠나요?\", \"새 점검표가 너무 길어 사용되지 않는다면 어떻게 보완하겠나요?\", \"손님 안내 문구를 바꿔 보고 싶다면 어떤 방식으로 효과를 확인하겠나요?\", \"잘 운영되던 개선 방법이 다시 흐트러지면 무엇을 점검하겠나요?\", \"불편하다는 느낌을 개선 과제로 만들려면 어떤 근거가 필요한가요?\", \"여러 개선 아이디어 중 먼저 시험할 것은 어떻게 고르겠나요?\", \"문제의 원인과 겉으로 보이는 현상을 어떻게 구분하겠나요?\", \"개선 효과를 확인할 때 속도 외에 어떤 변화를 살펴야 하나요?\", \"현장에서 일하는 동료들의 의견을 어떤 방식으로 모으겠나요?\", \"개선안을 작게 시험해야 하는 이유는 무엇이라고 생각하나요?\", \"실패한 시도에서 다음에 활용할 내용을 어떻게 남기겠나요?\", \"개인의 편리함이 매장 전체에 불편을 주지 않는지 어떻게 확인하겠나요?\", \"효과가 확인된 새 방식을 다른 직원에게 어떻게 전달하겠나요?\", \"업무가 익숙해진 뒤에도 개선할 점을 찾기 위해 어떤 습관을 두겠나요?\"]}, {\"name\": \"장기근속 의향\", \"questions\": [\"한 활동이나 일을 꾸준히 이어 가게 했던 요인은 무엇이었나요?\", \"처음 기대와 실제 업무가 달랐을 때 어떻게 판단하고 조정했나요?\", \"일을 계속할지 고민하며 필요한 정보를 확인했던 경험이 있나요?\", \"같은 역할 안에서 새로운 목표를 찾아 몰입한 경험을 말해 주세요.\", \"업무에 대한 만족도가 떨어졌을 때 원인을 살펴본 경험이 있나요?\", \"오래 함께한 조직에서 보람을 느꼈던 순간을 설명해 주세요.\", \"근무나 활동 조건에 대한 기대를 미리 이야기했던 경험이 있나요?\", \"역할의 발전 가능성을 확인하고 참여를 이어 간 경험을 말해 주세요.\", \"반복 업무 속에서 성장했다고 느꼈던 변화는 무엇이었나요?\", \"참여하던 일을 마무리할 때 충분한 인계를 준비했던 경험이 있나요?\", \"입사 후 업무 내용이 안내와 다르다고 느껴지면 어떻게 확인하겠나요?\", \"세 달이 지나 업무가 익숙해졌다면 다음 목표를 어떻게 정하겠나요?\", \"맡은 역할에서 배울 것이 줄었다고 느껴지면 누구와 무엇을 논의하겠나요?\", \"장기적으로 맡고 싶은 업무가 생기면 어떤 준비와 대화를 시작하겠나요?\", \"확정된 근무 조건이 지속적으로 지켜지지 않는다면 어떻게 문제를 제기하겠나요?\", \"바쁜 시기가 끝난 뒤 의욕이 낮아졌다면 어떤 부분을 돌아보겠나요?\", \"원하는 교육 기회가 바로 제공되기 어렵다면 어떤 대안을 논의하겠나요?\", \"자신의 역할이 계속 모호하다면 장기적인 업무 방향을 어떻게 확인하겠나요?\", \"근무 지속 여부를 결정해야 할 때 매장과 어떤 내용을 먼저 이야기하겠나요?\", \"퇴사를 결정하게 된다면 일정과 인계를 어떤 방식으로 조율하겠나요?\", \"이 직무에서 꾸준히 일하고 싶게 만드는 요소는 무엇인가요?\", \"입사 전에 반드시 확인하고 싶은 업무 조건은 무엇인가요?\", \"외식업의 반복 업무와 바쁜 시간대를 어떤 기대를 가지고 보고 있나요?\", \"첫 여섯 달 동안 어떤 업무를 안정적으로 해내고 싶나요?\", \"장기적으로 일할 매장을 고를 때 어떤 기준을 중요하게 보나요?\", \"오래 일하면서 배우고 싶은 기술이나 역할은 무엇인가요?\", \"근무 만족도를 매장과 정기적으로 이야기한다면 어떤 내용을 다루고 싶나요?\", \"무리 없이 지속할 수 있는 업무 범위와 성장 목표를 어떻게 조율하고 싶나요?\", \"직원이 오래 일할 수 있도록 매장과 직원이 각각 노력할 부분은 무엇인가요?\", \"이 매장에서 계속 성장할 수 있는지 입사 후 어떤 경험을 통해 판단하겠나요?\"]}]</script><script>\nconst BANK=JSON.parse(document.getElementById('bank').textContent);const $=id=>document.getElementById(id);let selected=[],chosen={},active=null,custom=[];const answerMemory={};const STORAGE='hiring-builder-v1';\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction save(){try{localStorage.setItem(STORAGE,JSON.stringify({selected,chosen,custom}))}catch{}}\nfunction status(t){$('status').textContent=t}\nfunction count(){return selected.reduce((n,id)=>n+(chosen[id]||[]).length,0)+custom.length}\nfunction picked(){return selected.reduce((n,id)=>n+(chosen[id]||[]).length,0)}\nfunction ready(){return selected.length>0&&picked()===10}\nfunction render(){ $('traits').innerHTML=BANK.map((t,id)=>`<button class=\"trait ${selected.includes(id)?'selected':''}\" data-trait=\"${id}\" aria-pressed=\"${selected.includes(id)}\" ${selected.length===3&&!selected.includes(id)?'disabled':''}>${selected.includes(id)?'✓ ':''}${esc(t.name)}</button>`).join('');$('traitCount').textContent=selected.length+' / 3';$('tabs').innerHTML=selected.map(id=>`<button data-tab=\"${id}\" class=\"${active===id?'selected':''}\" aria-pressed=\"${active===id}\">${esc(BANK[id].name)} ${(chosen[id]||[]).length}개</button>`).join('');renderQuestions();$('customList').innerHTML=custom.map((q,i)=>`<div class=\"customitem\"><span>${esc(q)}</span><button data-remove=\"${i}\" aria-label=\"추가 질문 ${i+1} 삭제\">삭제</button></div>`).join('');$('total').textContent='총 '+count()+'문항';$('share').disabled=!ready();$('remaining').textContent=ready()?'설문지가 준비됐어요. 링크를 만들어보세요.':selected.length?'기본 질문 '+picked()+'/10개 · '+(10-picked())+'개 더 선택':'인재상을 선택하고 질문을 골라주세요.';renderSurvey();save()}\nfunction renderQuestions(){if(active===null){$('questionList').innerHTML='<div class=\"empty\"><b>먼저 인재상을 골라주세요</b>선택한 인재상의 질문 30개가 여기에 나와요.</div>';return}const ids=chosen[active]||[];const top=$('questionList').scrollTop;$('questionList').innerHTML=BANK[active].questions.map((q,i)=>`<label class=\"qrow\"><input type=\"checkbox\" data-question=\"${i}\" ${ids.includes(i)?'checked':''} ${picked()>=10&&!ids.includes(i)?'disabled':''}><span><span class=\"type\">${i<10?'실제 경험':i<20?'상황 대응':'업무 태도'} · ${i+1}</span>${esc(q)}</span></label>`).join('');$('questionList').scrollTop=top}\nfunction entries(){return selected.map(id=>({name:BANK[id].name,items:(chosen[id]||[]).slice().sort((a,b)=>a-b).map(i=>({key:id+'-'+i,text:BANK[id].questions[i]}))})).filter(g=>g.items.length).concat(custom.length?[{name:'추가 질문',items:custom.map((text,i)=>({key:'c-'+i,text}))}]:[])}\nfunction renderSurvey(){let n=0;const groups=entries();$('survey').innerHTML=groups.length?groups.map(g=>`<h2 class=\"group-title\">${esc(g.name)} · ${g.items.length}문항</h2>`+g.items.map(q=>`<div class=\"answer\"><label for=\"a-${q.key}\">${++n}. ${esc(q.text)}</label><textarea id=\"a-${q.key}\" data-answer=\"${q.key}\" placeholder=\"답변을 입력해 주세요\">${esc(answerMemory[q.key]||'')}</textarea></div>`).join('')).join(''):'<div class=\"empty\"><b>질문을 고르면 설문지가 완성돼요</b>선택한 질문 아래에 답변 입력란이 생겨요.</div>'}\n$('traits').addEventListener('click',e=>{const b=e.target.closest('[data-trait]');if(!b)return;const id=+b.dataset.trait;if(selected.includes(id)){selected=selected.filter(x=>x!==id);delete chosen[id];if(active===id)active=selected[0]??null}else if(selected.length<3){selected.push(id);chosen[id]=[];active=id}status('');render()});$('tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){active=+b.dataset.tab;render()}});$('questionList').addEventListener('change',e=>{if(!e.target.matches('[data-question]'))return;const i=+e.target.dataset.question;if(e.target.checked&&picked()>=10){e.target.checked=false;return}chosen[active]=e.target.checked?[...(chosen[active]||[]),i]:(chosen[active]||[]).filter(x=>x!==i);render()});$('addCustom').onclick=()=>{const q=$('customText').value.trim();if(!q){status('추가할 질문을 먼저 적어주세요.');$('customText').focus();return}if(custom.length>=20){status('직접 질문은 최대 20개까지 추가할 수 있어요.');return}custom.push(q);$('customText').value='';status('질문을 추가했어요.');render()};$('customList').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){custom.splice(+b.dataset.remove,1);render()}};\nfunction encode(o){return btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(o)))).replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=+$/,'')}\nfunction decode(s){return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))))}\n$('share').onclick=()=>{if(!ready())return;const url=new URL(location.href);url.hash='survey='+encode({v:1,selected,chosen,custom});$('shareUrl').value=url.href;$('openSurvey').href=url.href;$('copyStatus').textContent='';if(location.protocol==='file:')$('shareNote').textContent='이 링크는 이 컴퓨터의 파일을 열어요. 다른 기기와 공유하려면 웹 게시가 필요해요.';$('linkDialog').showModal()};$('closeDialog').onclick=()=>$('linkDialog').close();$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('shareUrl').value);$('copyStatus').textContent='링크를 복사했어요.'}catch{$('shareUrl').select();$('copyStatus').textContent='주소를 선택했어요. 복사해서 사용해주세요.'}};\nlet surveyMode=false;try{if(location.hash.startsWith('#survey=')){const d=decode(location.hash.slice(8));if(d.v!==1||!Array.isArray(d.selected)||d.selected.length<1||d.selected.length>3||new Set(d.selected).size!==d.selected.length||!d.selected.every(id=>Number.isInteger(id)&&BANK[id]&&Array.isArray(d.chosen?.[id])&&d.chosen[id].length<=10&&new Set(d.chosen[id]).size===d.chosen[id].length&&d.chosen[id].every(i=>Number.isInteger(i)&&i>=0&&i<30))||d.selected.reduce((n,id)=>n+d.chosen[id].length,0)!==10||!Array.isArray(d.custom)||d.custom.length>20||!d.custom.every(q=>typeof q==='string'&&q.length<=500))throw Error();selected=d.selected;chosen=d.chosen;custom=d.custom;surveyMode=true;document.body.classList.add('standalone');document.title='외식업 신규 채용 설문지';try{Object.assign(answerMemory,JSON.parse(sessionStorage.getItem(location.hash)||'{}'))}catch{}}else{try{const d=JSON.parse(localStorage.getItem(STORAGE));if(d){selected=d.selected.filter(id=>Number.isInteger(id)&&BANK[id]).slice(0,3);chosen={};for(const id of selected)chosen[id]=[...new Set(d.chosen[id])].filter(i=>Number.isInteger(i)&&i>=0&&i<30).slice(0,10);custom=d.custom.filter(q=>typeof q==='string').slice(0,20)}}catch{}}if(!surveyMode){let remaining=10;for(const id of selected){chosen[id]=chosen[id].slice(0,remaining);remaining-=chosen[id].length}}active=selected[0]??null;render()}catch{document.body.classList.add('standalone');$('survey').innerHTML='<div class=\"empty\"><b>설문 링크를 확인해주세요</b>주소가 잘렸거나 올바르지 않아요. 생성한 링크 전체를 다시 열어주세요.</div>'}\ndocument.querySelectorAll('button:not([type])').forEach(b=>b.type='button');\n$('survey').addEventListener('input',e=>{if(e.target.matches('[data-answer]')){answerMemory[e.target.dataset.answer]=e.target.value;if(surveyMode)try{sessionStorage.setItem(location.hash,JSON.stringify(answerMemory))}catch{}}});\nif(surveyMode){for(const id of ['appName','appBirth','appPhone'])$(id).required=true;document.querySelectorAll('[data-answer]').forEach(t=>{t.required=true;t.maxLength=5000});$('appBirth').max=new Date().toISOString().slice(0,10)}\nlet submissionId=crypto.randomUUID();$('application').onsubmit=async e=>{e.preventDefault();if(!surveyMode)return;const b=$('submitApplication');b.disabled=true;$('submitStatus').textContent='답변을 저장하고 있어요.';try{const answers={};document.querySelectorAll('[data-answer]').forEach(t=>answers[t.dataset.answer]=t.value);const r=await fetch('/api/submissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:submissionId,survey:location.hash.slice(8),name:$('appName').value,birth:$('appBirth').value,phone:$('appPhone').value,answers})});if(!r.ok){const d=await r.json();throw Error(d.error||'저장하지 못했어요. 다시 시도해주세요.')}const form=$('application');form.replaceChildren();const h=document.createElement('h2');h.textContent='제출이 완료됐어요';const p=document.createElement('p');p.textContent='지원자 정보와 답변이 담당자에게 전달됐어요.';form.append(h,p);try{sessionStorage.removeItem(location.hash)}catch{}}catch(err){$('submitStatus').textContent=err.message;b.disabled=false}};\nif(!surveyMode){async function refreshUnread(){try{const r=await fetch('/api/submissions/summary');if(!r.ok)return;const d=await r.json();$('unreadBadge').textContent='미확인 '+d.unread+'건';$('unreadBadge').hidden=d.unread===0}catch{}}refreshUnread();window.addEventListener('focus',refreshUnread)}\n</script></body></html>\n";
